import libtmux, time, sys, subprocess, os, re
W=int(os.environ.get('W','80')); H=int(os.environ.get('H','24'))
server=libtmux.Server()
try:
    s=server.sessions.get(session_name="test", default=None)
    if s: s.kill()
except: pass
session=server.new_session(session_name="test", kill_session=True, attach=False)
pane=session.active_window.active_pane
subprocess.run(["tmux","resize-window","-t","test","-x",str(W),"-y",str(H)], capture_output=True)
pane.send_keys(sys.argv[1], enter=True); time.sleep(1.0)
def state(label):
    out=subprocess.check_output(["tmux","capture-pane","-t","test","-p","-e"]).decode().splitlines()
    plain=pane.capture_pane()
    print(f"=== {label} ===")
    # first data row label, last
    print(" header:", plain[3].rstrip() if len(plain)>3 else '')
    print(" firstrow:", plain[5].rstrip() if len(plain)>5 else '')
    for i,l in enumerate(out):
        if '48;2;60;60;60' in l or '[1;4m' in l:
            # clean repr around
            print(f"  sel line {i}: {l!r}")
            print(f"  plain   : {plain[i]!r}")
state("initial")
for key in sys.argv[2:]:
    if key.startswith("lit:"): pane.send_keys(key[4:], enter=False, literal=True)
    elif key.startswith("repeat:"):
        _,n,k=key.split(':',2)
        for _ in range(int(n)): pane.send_keys(k, enter=False); time.sleep(0.03)
    else: pane.send_keys(key, enter=False)
    time.sleep(0.3); state(key)
