import struct
class R:
 def __init__(self,b,pos=0): self.b=b; self.p=pos
 def byte(self):
  v=self.b[self.p]; self.p+=1; return v
 def varint(self):
  shift=0; result=0
  while True:
   by=self.byte(); result |= (by & 0x7f)<<shift; shift+=7
   if not (by & 0x80): break
  return result
 def zigzag(self):
  n=self.varint(); return (n>>1) ^ -(n&1)
 def bytes(self,n):
  v=self.b[self.p:self.p+n]; self.p+=n; return v

def parse_value(r,t):
 # compact type ids
 if t==1: return True  # only in field header context handled separately? For collection bool elems byte value
 if t==2: return False
 if t==3:
  v=r.byte(); return v-256 if v>127 else v
 if t in (4,5,6): return r.zigzag()
 if t==7: return struct.unpack('<d', r.bytes(8))[0]
 if t==8:
  n=r.varint(); return r.bytes(n)
 if t in (9,10):
  h=r.byte(); size=h>>4; et=h&0xf
  if size==15: size=r.varint()
  return [parse_value(r,et) for _ in range(size)]
 if t==11:
  size=r.varint()
  if size==0: return {}
  h=r.byte(); kt=h>>4; vt=h&0xf
  return {parse_value(r,kt):parse_value(r,vt) for _ in range(size)}
 if t==12: return parse_struct(r)
 if t==13: return r.bytes(16)
 raise ValueError(f"type {t} at {r.p}")

def parse_struct(r):
 out={}; last=0
 while True:
  h=r.byte()
  if h==0: break
  delta=h>>4; t=h&0xf
  if delta==0: fid=r.zigzag()
  else: fid=last+delta
  last=fid
  if t==1: val=True
  elif t==2: val=False
  else: val=parse_value(r,t)
  out[fid]=val
 return out

def footer(path):
