use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq)]
pub enum TValue {
    Bool(bool),
    Byte(i8),
    Int(i64),
    Double(f64),
    Binary(Vec<u8>),
    List(Vec<TValue>),
    Map(Vec<(TValue, TValue)>),
    Struct(BTreeMap<i16, TValue>),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TError {
    Eof,
    Protocol,
}

pub struct Reader<'a> {
    pub buf: &'a [u8],
    pub pos: usize,
}

impl<'a> Reader<'a> {
    pub fn new(buf: &'a [u8]) -> Self { Self { buf, pos: 0 } }
    pub fn byte(&mut self) -> Result<u8, TError> {
        let v = *self.buf.get(self.pos).ok_or(TError::Eof)?;
        self.pos += 1;
        Ok(v)
    }
    pub fn bytes(&mut self, n: usize) -> Result<&'a [u8], TError> {
        if self.pos.checked_add(n).map_or(true, |e| e > self.buf.len()) { return Err(TError::Eof); }
        let s = &self.buf[self.pos..self.pos+n];
        self.pos += n;
        Ok(s)
    }
    pub fn varint(&mut self) -> Result<u64, TError> {
        let mut result: u64 = 0;
        let mut shift = 0u32;
        loop {
            let b = self.byte()?;
            if shift >= 64 { return Err(TError::Protocol); }
            result |= ((b & 0x7f) as u64) << shift;
            shift += 7;
            if b & 0x80 == 0 { break; }
            if shift > 70 { return Err(TError::Protocol); }
        }
        Ok(result)
    }
    pub fn zigzag(&mut self) -> Result<i64, TError> {
        let n = self.varint()?;
        Ok(((n >> 1) as i64) ^ -((n & 1) as i64))
    }
    pub fn value(&mut self, ty: u8) -> Result<TValue, TError> {
        match ty {
            1 => {
                // In collections, booleans are written as a single byte 1/2.
                // (Field-header booleans are handled in parse_struct.)
                let b = self.byte()?;
                Ok(TValue::Bool(b == 1))
            }
            2 => Ok(TValue::Bool(false)),
            3 => Ok(TValue::Byte(self.byte()? as i8)),
            4 | 5 | 6 => Ok(TValue::Int(self.zigzag()?)),
            7 => {
                let b = self.bytes(8)?;
                Ok(TValue::Double(f64::from_le_bytes(b.try_into().unwrap())))
            }
            8 => {
                let n = self.varint()? as usize;
                Ok(TValue::Binary(self.bytes(n)?.to_vec()))
            }
            9 | 10 => {
                let h = self.byte()?;
                let mut size = (h >> 4) as usize;
                let et = h & 0xf;
                if size == 15 { size = self.varint()? as usize; }
                if size > 10_000_000 { return Err(TError::Protocol); }
                let mut v = Vec::with_capacity(size.min(1024));
                for _ in 0..size { v.push(self.value(et)?); }
                Ok(TValue::List(v))
            }
            11 => {
                let size = self.varint()? as usize;
                if size == 0 { return Ok(TValue::Map(vec![])); }
                if size > 10_000_000 { return Err(TError::Protocol); }
                let h = self.byte()?;
                let (kt, vt) = (h >> 4, h & 0xf);
                let mut v = Vec::new();
                for _ in 0..size {
                    let k = self.value(kt)?;
                    let val = self.value(vt)?;
                    v.push((k, val));
                }
                Ok(TValue::Map(v))
            }
            12 => Ok(TValue::Struct(self.parse_struct()?)),
            13 => Ok(TValue::Binary(self.bytes(16)?.to_vec())),
            _ => Err(TError::Protocol),
        }
    }
    pub fn parse_struct(&mut self) -> Result<BTreeMap<i16, TValue>, TError> {
        let mut out = BTreeMap::new();
        let mut last: i16 = 0;
        loop {
            let h = self.byte()?;
            if h == 0 { break; }
            let delta = h >> 4;
            let ty = h & 0xf;
            let fid: i16 = if delta == 0 {
                let v = self.zigzag()?;
                i16::try_from(v).map_err(|_| TError::Protocol)?
            } else {
                last.checked_add(delta as i16).ok_or(TError::Protocol)?
            };
            last = fid;
            let val = match ty {
                1 => TValue::Bool(true),
                2 => TValue::Bool(false),
                _ => self.value(ty)?,
            };
            out.insert(fid, val);
        }
        Ok(out)
    }
}

pub type TStruct = BTreeMap<i16, TValue>;

pub fn get<'a>(s: &'a TStruct, id: i16) -> Option<&'a TValue> { s.get(&id) }
pub fn as_int(v: Option<&TValue>) -> Option<i64> {
    match v { Some(TValue::Int(i)) => Some(*i), Some(TValue::Byte(b)) => Some(*b as i64), _ => None }
}
pub fn as_bool(v: Option<&TValue>) -> Option<bool> {
    match v { Some(TValue::Bool(b)) => Some(*b), _ => None }
}
pub fn as_bytes(v: Option<&TValue>) -> Option<&[u8]> {
    match v { Some(TValue::Binary(b)) => Some(b), _ => None }
}
pub fn as_str(v: Option<&TValue>) -> Option<String> {
    as_bytes(v).map(|b| String::from_utf8_lossy(b).into_owned())
}
pub fn as_list(v: Option<&TValue>) -> Option<&Vec<TValue>> {
    match v { Some(TValue::List(l)) => Some(l), _ => None }
}
pub fn as_struct(v: Option<&TValue>) -> Option<&TStruct> {
    match v { Some(TValue::Struct(s)) => Some(s), _ => None }
}
RS
