{"command":"cat > src/meta.rs <<'RS'
use crate::thrift::*;
use std::collections::BTreeMap;

#[derive(Debug, Clone)]
pub struct Statistics {
    pub max: Option<Vec<u8>>,
    pub min: Option<Vec<u8>>,
    pub null_count: Option<i64>,
    pub distinct_count: Option<i64>,
    pub max_value: Option<Vec<u8>>,
    pub min_value: Option<Vec<u8>>,
}
impl Statistics {
    pub fn min_bytes(&self) -> Option<&[u8]> { self.min_value.as_deref().or(self.min.as_deref()) }
    pub fn max_bytes(&self) -> Option<&[u8]> { self.max_value.as_deref().or(self.max.as_deref()) }
    fn parse(s: &TStruct) -> Self {
        Self {
            max: as_bytes(get(s,1)).map(|b| b.to_vec()),
            min: as_bytes(get(s,2)).map(|b| b.to_vec()),
            null_count: as_int(get(s,3)),
            distinct_count: as_int(get(s,4)),
            max_value: as_bytes(get(s,5)).map(|b| b.to_vec()),
            min_value: as_bytes(get(s,6)).map(|b| b.to_vec()),
        }
    }
    pub fn parse_opt(v: Option<&TValue>) -> Option<Self> { as_struct(v).map(Self::parse) }
}

#[derive(Debug, Clone)]
pub struct ColumnChunk {
    pub file_offset: i64,
    pub physical_type: i32,
    pub encodings: Vec<i32>,
    pub path: Vec<String>,
    pub codec: i32,
    pub num_values: i64,
    pub total_uncompressed_size: i64,
    pub total_compressed_size: i64,
    pub data_page_offset: i64,
    pub index_page_offset: Option<i64>,
    pub dictionary_page_offset: Option<i64>,
    pub statistics: Option<Statistics>,
    pub has_encoding_stats: bool,
    pub bloom_filter_offset: Option<i64>,
    pub offset_index_offset: Option<i64>,
    pub column_index_offset: Option<i64>,
}

#[derive(Debug, Clone)]
pub struct RowGroup {
    pub columns: Vec<ColumnChunk>,
    pub total_byte_size: i64,
    pub num_rows: i64,
    pub file_offset: Option<i64>,
    pub total_compressed_size: Option<i64>,
    pub ordinal: Option<i64>,
}
impl RowGroup {
    pub fn compressed(&self) -> i64 { self.columns.iter().map(|c| c.total_compressed_size).sum() }
    pub fn uncompressed(&self) -> i64 { self.columns.iter().map(|c| c.total_uncompressed_size).sum() }
}

#[derive(Debug, Clone)]
pub struct SchemaNode {
    pub name: String,
    pub physical: Option<i32>,
    pub type_length: Option<i32>,
    pub repetition: Option<i32>,
    pub converted: Option<i32>,
    pub scale: Option<i32>,
    pub precision: Option<i32>,
    pub field_id: Option<i32>,
    pub logical: Option<TStruct>,
    pub children: Vec<SchemaNode>,
}
impl SchemaNode {
    pub fn is_leaf(&self) -> bool { self.physical.is_some() }
    pub fn repetition_name(&self) -> &'static str {
        match self.repetition { Some(0) => "REQUIRED", Some(1) => "OPTIONAL", Some(2) => "REPEATED", _ => "REQUIRED" }
    }
}

#[derive(Debug, Clone)]
pub struct FileMeta {
    pub version: i32,
    pub schema_raw: Vec<TStruct>,
    pub root: SchemaNode,
    pub num_rows: i64,
    pub row_groups: Vec<RowGroup>,
    pub key_value: Vec<(String, Option<String>)>,
    pub created_by: Option<String>,
}

pub fn physical_name(t: i32) -> &'static str {
    match t { 0=>"BOOLEAN",1=>"INT32",2=>"INT64",3=>"INT96",4=>"FLOAT",5=>"DOUBLE",6=>"BYTE_ARRAY",7=>"FIXED_LEN_BYTE_ARRAY", _=>"UNKNOWN" }
}
pub fn encoding_name(e: i32) -> String {
    match e { 0=>"PLAIN",2=>"PLAIN_DICTIONARY",3=>"RLE",4=>"BIT_PACKED",5=>"DELTA_BINARY_PACKED",6=>"DELTA_LENGTH_BYTE_ARRAY",7=>"DELTA_BYTE_ARRAY",8=>"RLE_DICTIONARY",9=>"BYTE_STREAM_SPLIT", _=> return format!("UNKNOWN({})", e) }.to_string()
}
pub fn codec_debug(c: i32) -> String {
    match c {
        0=>"UNCOMPRESSED".into(), 1=>"SNAPPY".into(),
        2=>"GZIP(GzipLevel(6))".into(), 3=>"LZO".into(), 4=>"BROTLI(BrotliLevel(1))".into(),
        5=>"LZ4".into(), 6=>"ZSTD(ZstdLevel(1))".into(), 7=>"LZ4_RAW".into(),
        _=>format!("UNKNOWN({})", c)
    }
}

fn build_node(elems: &[TStruct], idx: &mut usize) -> Result<SchemaNode, String> {
    if *idx >= elems.len() { return Err("Parquet error: Could not parse metadata: protocol error".into()); }
    let e = &elems[*idx];
    *idx += 1;
    let physical = as_int(get(e,1)).map(|v| v as i32);
    if let Some(t) = physical {
        if !(0..=7).contains(&t) {
            return Err(format!("Parquet error: unexpected parquet type: {}", t));
        }
    }
    let nchild = as_int(get(e,5)).unwrap_or(0);
    let mut children = Vec::new();
    for _ in 0..nchild.max(0) { children.push(build_node(elems, idx)?); }
    Ok(SchemaNode {
        name: as_str(get(e,4)).unwrap_or_default(),
        physical,
        type_length: as_int(get(e,2)).map(|v| v as i32),
        repetition: as_int(get(e,3)).map(|v| v as i32),
        converted: as_int(get(e,6)).map(|v| v as i32),
        scale: as_int(get(e,7)).map(|v| v as i32),
        precision: as_int(get(e,8)).map(|v| v as i32),
        field_id: as_int(get(e,9)).map(|v| v as i32),
        logical: as_struct(get(e,10)).cloned(),
        children,
    })
}

pub fn parse_footer(bytes: &[u8]) -> Result<FileMeta, String> {
    let len = bytes.len();
    if len < 8 {
        return Err(format!("EOF: Parquet file too small. Size is {} but need 8", len));
    }
    let magic = &bytes[len-4..];
    if magic == b"PARE" {
        return Err("Parquet error: Parquet file has an encrypted footer but the encryption feature is disabled".into());
    }
    if magic != b"PAR1" {
        return Err("Parquet error: Invalid Parquet file. Corrupt footer".into());
    }
    let meta_len = u32::from_le_bytes(bytes[len-8..len-4].try_into().unwrap()) as usize;
    let need = meta_len.checked_add(8).unwrap_or(usize::MAX);
    if need > len {
        return Err(format!("EOF: Parquet file too small. Size is {} but need {}", len, need));
    }
    let start = len - 8 - meta_len;
    let mut r = Reader::new(&bytes[start..len-8]);
    let meta = r.parse_struct().map_err(|e| match e {
        TError::Eof => "Parquet error: Could not parse metadata: end of file".to_string(),
        TError::Protocol => "Parquet error: Could not parse metadata: protocol error".to_string(),
    })?;
    // Schema elements
    let mut schema_raw: Vec<TStruct> = Vec::new();
    if let Some(list) = as_list(get(&meta,2)) {
        for v in list { if let Some(s) = as_struct(Some(v)) { schema_raw.push(s.clone()); } }
    }
    if schema_raw.is_empty() {
        return Err("Parquet error: Could not parse metadata: protocol error".into());
    }
    // Validate column chunk physical types too (like parquet crate schema conversion happens first;
    // build_node validates schema element types).
    let mut idx = 0usize;
    let root = build_node(&schema_raw, &mut idx)?;
    let mut row_groups = Vec::new();
    if let Some(rgs) = as_list(get(&meta,4)) {
        for rgv in rgs {
            let Some(rg) = as_struct(Some(rgv)) else { continue };
            let mut cols = Vec::new();
            if let Some(clist) = as_list(get(rg,1)) {
                for cv in clist {
                    let Some(c) = as_struct(Some(cv)) else { continue };
                    let md = as_struct(get(c,3)).cloned().unwrap_or_default();
                    let ptype = as_int(get(&md,1)).unwrap_or(0) as i32;
                    // parquet crate would already have errored on schema type above.
                    let encodings = as_list(get(&md,2)).map(|l| l.iter().filter_map(|x| as_int(Some(x)).map(|v| v as i32)).collect()).unwrap_or_default();
                    let path = as_list(get(&md,3)).map(|l| l.iter().filter_map(|x| as_str(Some(x))).collect()).unwrap_or_default();
                    cols.push(ColumnChunk {
                        file_offset: as_int(get(c,2)).unwrap_or(0),
                        physical_type: ptype,
                        encodings,
                        path,
                        codec: as_int(get(&md,4)).unwrap_or(0) as i32,
                        num_values: as_int(get(&md,5)).unwrap_or(0),
                        total_uncompressed_size: as_int(get(&md,6)).unwrap_or(0),
                        total_compressed_size: as_int(get(&md,7)).unwrap_or(0),
                        data_page_offset: as_int(get(&md,9)).unwrap_or(0),
                        index_page_offset: as_int(get(&md,10)),
                        dictionary_page_offset: as_int(get(&md,11)),
                        statistics: Statistics::parse_opt(get(&md,12)),
                        has_encoding_stats: as_list(get(&md,13)).map(|l| !l.is_empty()).unwrap_or(false),
                        bloom_filter_offset: as_int(get(&md,14)).or_else(|| as_int(get(c,10))),
                        offset_index_offset: as_int(get(c,4)),
                        column_index_offset: as_int(get(c,6)),
                    });
                }
            }
            row_groups.push(RowGroup {
                columns: cols,
                total_byte_size: as_int(get(rg,2)).unwrap_or(0),
                num_rows: as_int(get(rg,3)).unwrap_or(0),
                file_offset: as_int(get(rg,5)),
                total_compressed_size: as_int(get(rg,6)),
                ordinal: as_int(get(rg,7)),
            });
        }
    }
    let mut kv = Vec::new();
    if let Some(list) = as_list(get(&meta,5)) {
        for v in list {
            if let Some(s) = as_struct(Some(v)) {
                kv.push((as_str(get(s,1)).unwrap_or_default(), as_str(get(s,2))));
            }
        }
    }
    Ok(FileMeta {
        version: as_int(get(&meta,1)).unwrap_or(0) as i32,
        schema_raw,
        root,
        num_rows: as_int(get(&meta,3)).unwrap_or(0),
        row_groups,
        key_value: kv,
        created_by: as_str(get(&meta,6)),
    })
}

/// Flatten schema tree in preorder (including root). Returns (node ref via path indices, depth, is_last flags...)
#[derive(Debug, Clone)]
pub struct FlatNode {
    pub name: String,
    pub depth: usize,
    pub is_leaf: bool,
    pub leaf_index: Option<usize>,
    pub node_path: Vec<usize>, // child indices from root
    pub tree_line: String,
    pub repetition: Option<i32>,
    pub physical: Option<i32>,
}

pub fn node_at<'a>(root: &'a SchemaNode, path: &[usize]) -> &'a SchemaNode {
    let mut n = root;
    for &i in path { n = &n.children[i]; }
    n
}

pub fn flatten_schema(root: &SchemaNode) -> Vec<FlatNode> {
    let mut out = Vec::new();
    let mut leaf_counter = 0usize;
    // root line
    out.push(FlatNode { name: "root".into(), depth: 0, is_leaf: false, leaf_index: None, node_path: vec![], tree_line: "└─ root".into(), repetition: root.repetition, physical: root.physical });
    fn rec(node: &SchemaNode, depth: usize, prefix: &str, path: Vec<usize>, out: &mut Vec<FlatNode>, leaf_counter: &mut usize) {
        let n = node.children.len();
        for (i, ch) in node.children.iter().enumerate() {
            let last = i + 1 == n;
            let connector = if last { "└─ " } else { "├─ " };
            let line = format!("{}{}{}", prefix, connector, ch.name);
            let mut p = path.clone(); p.push(i);
            let li = if ch.is_leaf() { let v = *leaf_counter; *leaf_counter += 1; Some(v) } else { None };
            out.push(FlatNode { name: ch.name.clone(), depth, is_leaf: ch.is_leaf(), leaf_index: li, node_path: p.clone(), tree_line: line, repetition: ch.repetition, physical: ch.physical });
            let child_prefix = format!("{}{}", prefix, if last { "   " } else { "│  " });
            rec(ch, depth+1, &child_prefix, p, out, leaf_counter);
        }
    }
    rec(root, 1, "   ", vec![], &mut out, &mut leaf_counter);
    out
}

pub fn leaf_count(root: &SchemaNode) -> usize {
    if root.is_leaf() { 1 } else { root.children.iter().map(leaf_count).sum() }
}
RS
"}

