/// Flatten schema tree in preorder (including root). Returns (node ref via path indices, depth, is_last flags...)
#[derive(Debug, Clone)]
pub struct FlatNode {
    pub name: String,
    pub depth: usize,
    pub is_leaf: bool,
    pub leaf_index: Option<usize>,
    pub node_path: Vec<usize>, // child indices from root
    pub tree_line: String,
    pub repetition: Option<i32>,
    pub physical: Option<i32>,
}

pub fn node_at<'a>(root: &'a SchemaNode, path: &[usize]) -> &'a SchemaNode {
    let mut n = root;
    for &i in path { n = &n.children[i]; }
    n
}

pub fn flatten_schema(root: &SchemaNode) -> Vec<FlatNode> {
    let mut out = Vec::new();
    let mut leaf_counter = 0usize;
    // root line
    out.push(FlatNode { name: "root".into(), depth: 0, is_leaf: false, leaf_index: None, node_path: vec![], tree_line: "└─ root".into(), repetition: root.repetition, physical: root.physical });
    fn rec(node: &SchemaNode, depth: usize, prefix: &str, path: Vec<usize>, out: &mut Vec<FlatNode>, leaf_counter: &mut usize) {
        let n = node.children.len();
        for (i, ch) in node.children.iter().enumerate() {
            let last = i + 1 == n;
            let connector = if last { "└─ " } else { "├─ " };
            let line = format!("{}{}{}", prefix, connector, ch.name);
            let mut p = path.clone(); p.push(i);
            let li = if ch.is_leaf() { let v = *leaf_counter; *leaf_counter += 1; Some(v) } else { None };
            out.push(FlatNode { name: ch.name.clone(), depth, is_leaf: ch.is_leaf(), leaf_index: li, node_path: p.clone(), tree_line: line, repetition: ch.repetition, physical: ch.physical });
            let child_prefix = format!("{}{}", prefix, if last { "   " } else { "│  " });
            rec(ch, depth+1, &child_prefix, p, out, leaf_counter);
        }
    }
    rec(root, 1, "   ", vec![], &mut out, &mut leaf_counter);
    out
}

pub fn leaf_count(root: &SchemaNode) -> usize {
    if root.is_leaf() { 1 } else { root.children.iter().map(leaf_count).sum() }
}
