        let tag = input[pos]; pos += 1;
        match tag & 0x3 {
            0 => {
                let mut len = (tag >> 2) as usize;
                if len >= 60 {
                    let nbytes = len - 59;
                    if pos + nbytes > input.len() { return Err("snappy eof".into()); }
                    let mut v: usize = 0;
                    for i in 0..nbytes { v |= (input[pos+i] as usize) << (8*i); }
                    pos += nbytes;
                    len = v;
                }
                len += 1;
                if pos + len > input.len() { return Err("snappy eof literal".into()); }
                out.extend_from_slice(&input[pos..pos+len]); pos += len;
            }
            1 => {
                let len = 4 + (((tag >> 2) & 0x7) as usize);
                if pos >= input.len() { return Err("snappy eof".into()); }
                let offset = (((tag as usize) >> 5) << 8) | input[pos] as usize; pos += 1;
                copy_match(&mut out, offset, len)?;
            }
            2 => {
                let len = 1 + (tag >> 2) as usize;
                if pos + 2 > input.len() { return Err("snappy eof".into()); }
                let offset = u16::from_le_bytes([input[pos], input[pos+1]]) as usize; pos += 2;
                copy_match(&mut out, offset, len)?;
            }
            _ => {
                let len = 1 + (tag >> 2) as usize;
                if pos + 4 > input.len() { return Err("snappy eof".into()); }
                let offset = u32::from_le_bytes([input[pos],input[pos+1],input[pos+2],input[pos+3]]) as usize; pos += 4;
                copy_match(&mut out, offset, len)?;
            }
        }
    }
    Ok(out)
}
fn copy_match(out: &mut Vec<u8>, offset: usize, len: usize) -> Result<(), String> {
    if offset == 0 || offset > out.len() { return Err("snappy offset".into()); }
    let start = out.len() - offset;
    for i in 0..len { let b = out[start+i]; out.push(b); }
    Ok(())
}

pub fn lz4_block_decompress(input: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    let mut out: Vec<u8> = Vec::with_capacity(expected);
    let mut pos = 0usize;
    while pos < input.len() {
        let token = input[pos]; pos += 1;
        let mut lit_len = (token >> 4) as usize;
        if lit_len == 15 {
            loop {
                let b = *input.get(pos).ok_or("lz4 eof")?; pos += 1;
                lit_len += b as usize;
                if b != 255 { break; }
            }
        }
        if pos + lit_len > input.len() { return Err("lz4 literal eof".into()); }
        out.extend_from_slice(&input[pos..pos+lit_len]); pos += lit_len;
        if pos >= input.len() { break; }
        if pos + 2 > input.len() { return Err("lz4 offset eof".into()); }
        let offset = u16::from_le_bytes([input[pos], input[pos+1]]) as usize; pos += 2;
        let mut match_len = (token & 0xf) as usize;
        if match_len == 15 {
            loop {
                let b = *input.get(pos).ok_or("lz4 eof")?; pos += 1;
                match_len += b as usize;
                if b != 255 { break; }
            }
        }
        match_len += 4;
        if offset == 0 || offset > out.len() { return Err("lz4 offset".into()); }
        let start = out.len() - offset;
        for i in 0..match_len { let b = out[start+i]; out.push(b); }
        if expected > 0 && out.len() >= expected { break; }
    }
    Ok(out)
}

#[cfg(target_os = "linux")]
mod ffi {
    use std::os::raw::{c_char, c_int, c_ulonglong};
    extern "C" {
        pub fn ZSTD_decompress(dst: *mut core::ffi::c_void, dst_capacity: usize, src: *const core::ffi::c_void, src_size: usize) -> usize;
        pub fn ZSTD_isError(code: usize) -> u32;
        pub fn BrotliDecoderDecompress(encoded_size: usize, encoded: *const u8, decoded_size: *mut usize, decoded: *mut u8) -> c_int;
        #[allow(dead_code)]
        pub fn ZSTD_getErrorName(code: usize) -> *const c_char;
        #[allow(dead_code)]
        pub fn ZSTD_findDecompressedSize(src: *const core::ffi::c_void, src_size: usize) -> c_ulonglong;
    }
}

pub fn zstd_decompress(input: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    #[cfg(target_os = "linux")]
    unsafe {
        let mut out = vec![0u8; expected];
        let n = ffi::ZSTD_decompress(out.as_mut_ptr() as *mut _, expected, input.as_ptr() as *const _, input.len());
        if ffi::ZSTD_isError(n) != 0 { return Err("zstd decompression error".into()); }
        out.truncate(n);
        Ok(out)
    }
    #[cfg(not(target_os = "linux"))]
    { Err("zstd unsupported".into()) }
}
pub fn brotli_decompress(input: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    #[cfg(target_os = "linux")]
    unsafe {
        let mut out = vec![0u8; expected];
        let mut out_len = expected;
        let rc = ffi::BrotliDecoderDecompress(input.len(), input.as_ptr(), &mut out_len, out.as_mut_ptr());
        if rc != 1 { return Err("brotli decompression error".into()); }
        out.truncate(out_len);
        Ok(out)
    }
    #[cfg(not(target_os = "linux"))]
    { Err("brotli unsupported".into()) }
}

pub fn decompress(codec: i32, input: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    match codec {
        0 => Ok(input.to_vec()),
        1 => {
            // Some writers use framed snappy (stream identifier). Detect it.
            if input.starts_with(&[0xff, 0x06, 0x00, 0x00, b's', b'N', b'a', b'P', b'p', b'Y']) {
                framed_snappy_decompress(input, expected)
            } else {
                snappy_decompress(input, expected)
            }
        }
        2 => {
            let mut d = flate2::read::GzDecoder::new(input);
            let mut out = Vec::with_capacity(expected);
            d.read_to_end(&mut out).map_err(|e| e.to_string())?;
            Ok(out)
        }
        4 => brotli_decompress(input, expected),
        5 => {
            // Deprecated LZ4 in parquet: Hadoop framing inserts per-block headers.
            // Try raw block first; if size doesn't match, try Hadoop-style framed.
            match lz4_block_decompress(input, expected) {
                Ok(v) if v.len() == expected => Ok(v),
                _ => lz4_hadoop_decompress(input, expected).or_else(|_| lz4_block_decompress(input, expected)),
            }
        }
        6 => zstd_decompress(input, expected),
        7 => lz4_block_decompress(input, expected),
        3 => Err("LZO decompression not supported".into()),
        _ => Err(format!("unsupported codec {}", codec)),
    }
}

fn lz4_hadoop_decompress(input: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    // Hadoop Lz4Codec (used by older parquet LZ4): stream is built from blocks.
    // Each block is preceded by: 4-byte BE uncompressed length? and 4-byte BE compressed length
    // in some variants, plus a 4-byte checksum in others. Another variant used by
    // parquet-cpp's deprecated LZ4 codec prefixes the whole page with the
    // uncompressed size as 8-byte little endian / 4-byte..
    // We try a few layouts and accept the one yielding `expected` bytes.
    // Layout A: entire input after first 8 bytes (two BE u32: uncomp, comp of the single block)
    if input.len() > 8 {
        if let Ok(v) = lz4_block_decompress(&input[8..], expected) {
            if v.len() == expected { return Ok(v); }
        }
    }
    // Layout B: repeated blocks [u32 BE comp_len][u32 BE uncomp_len][block]...
    {
        let mut pos = 0; let mut out = Vec::new(); let mut ok = true;
        while pos + 8 <= input.len() {
            let clen = u32::from_be_bytes(input[pos..pos+4].try_into().unwrap()) as usize;
            let ulen = u32::from_be_bytes(input[pos+4..pos+8].try_into().unwrap()) as usize;
            pos += 8;
            if clen == 0 { break; }
            if pos + clen > input.len() { ok = false; break; }
            match lz4_block_decompress(&input[pos..pos+clen], ulen) {
                Ok(v) => out.extend_from_slice(&v), Err(_) => { ok=false; break; }
            }
            pos += clen;
        }
        if ok && out.len() == expected { return Ok(out); }
    }
    // Layout C: [u32 BE uncomp_len][u32 BE comp_len] swapped
    {
        let mut pos = 0; let mut out = Vec::new(); let mut ok = true;
        while pos + 8 <= input.len() {
            let ulen = u32::from_be_bytes(input[pos..pos+4].try_into().unwrap()) as usize;
            let clen = u32::from_be_bytes(input[pos+4..pos+8].try_into().unwrap()) as usize;
            pos += 8;
            if clen == 0 { break; }
            if pos + clen > input.len() { ok = false; break; }
            match lz4_block_decompress(&input[pos..pos+clen], ulen) {
                Ok(v) => out.extend_from_slice(&v), Err(_) => { ok=false; break; }
            }
            pos += clen;
        }
        if ok && out.len() == expected { return Ok(out); }
    }
    Err("lz4 hadoop".into())
}

fn framed_snappy_decompress(input: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    let mut out = Vec::with_capacity(expected);
    let mut pos = 0usize;
    while pos + 4 <= input.len() {
        let ty = input[pos];
        let len = (input[pos+1] as usize) | ((input[pos+2] as usize) << 8) | ((input[pos+3] as usize) << 16);
        pos += 4;
        if pos + len > input.len() { return Err("snappy framed eof".into()); }
        let chunk = &input[pos..pos+len]; pos += len;
        match ty {
            0x00 => { // compressed data, first 4 bytes checksum
                if chunk.len() < 4 { return Err("snappy frame".into()); }
                let v = snappy_decompress(&chunk[4..], expected)?;
                out.extend_from_slice(&v);
            }
            0x01 => { // uncompressed, 4 bytes checksum
                if chunk.len() < 4 { return Err("snappy frame".into()); }
                out.extend_from_slice(&chunk[4..]);
            }
            0xff => {} // stream identifier
            _ => {} // skippable
        }
    }
    Ok(out)
}
