use crate::codec::decompress;
use crate::meta::ColumnChunk;
use crate::thrift::*;

#[derive(Debug, Clone, PartialEq)]
pub enum PhysValue {
    Bool(bool),
    I32(i32),
    I64(i64),
    Int96([u8;12]),
    F32(f32),
    F64(f64),
    Bytes(Vec<u8>),
