fn bits_needed(max: u16) -> u8 {
    if max == 0 { 0 } else { 16 - (max as u16).leading_zeros() as u8 }
}

fn read_uleb(data: &[u8], pos: &mut usize) -> Result<u64, String> {
    let mut result: u64 = 0; let mut shift = 0;
    loop {
        let b = *data.get(*pos).ok_or("unexpected eof")?; *pos += 1;
        result |= ((b & 0x7f) as u64) << shift; shift += 7;
        if b & 0x80 == 0 { break; }
        if shift > 70 { return Err("varint too long".into()); }
    }
    Ok(result)
}
fn read_zigzag(data: &[u8], pos: &mut usize) -> Result<i64, String> {
    let n = read_uleb(data, pos)?;
    Ok(((n >> 1) as i64) ^ -((n & 1) as i64))
}

struct LsbBits<'a> { data: &'a [u8], bit_pos: usize }
impl<'a> LsbBits<'a> {
    fn new(data: &'a [u8]) -> Self { Self { data, bit_pos: 0 } }
    fn get(&mut self, n: u8) -> u32 {
        let mut v: u32 = 0;
        for i in 0..n {
            let byte = self.data.get(self.bit_pos / 8).copied().unwrap_or(0);
            let bit = (byte >> (self.bit_pos % 8)) & 1;
            v |= (bit as u32) << i;
            self.bit_pos += 1;
        }
        v
    }
}
struct MsbBits<'a> { data: &'a [u8], bit_pos: usize }
impl<'a> MsbBits<'a> {
    fn new(data: &'a [u8]) -> Self { Self { data, bit_pos: 0 } }
    fn get(&mut self, n: u8) -> u32 {
        let mut v: u32 = 0;
        for _ in 0..n {
            let byte = self.data.get(self.bit_pos / 8).copied().unwrap_or(0);
            let bit = (byte >> (7 - (self.bit_pos % 8))) & 1;
            v = (v << 1) | bit as u32;
            self.bit_pos += 1;
        }
        v
    }
}

pub fn decode_rle_hybrid(data: &[u8], bit_width: u8, count: usize) -> Result<Vec<u32>, String> {
    let mut out = Vec::with_capacity(count);
    let mut pos = 0usize;
    while out.len() < count {
        if pos >= data.len() {
            // Pad with zeros if data ran out (can happen for bit_width 0 rep levels in V2)
            out.resize(count, 0);
            break;
        }
        let header = read_uleb(data, &mut pos)?;
        if header & 1 == 0 {
            let run = (header >> 1) as usize;
            let byte_len = (bit_width as usize + 7) / 8;
            let mut v: u32 = 0;
            for i in 0..byte_len {
                v |= (*data.get(pos+i).ok_or("rle eof")? as u32) << (8*i);
            }
            pos += byte_len;
            let take = run.min(count - out.len());
            out.extend(std::iter::repeat(v).take(take));
        } else {
            let groups = (header >> 1) as usize;
            let total = groups * 8;
            let byte_len = groups * bit_width as usize;
            if pos + byte_len > data.len() && bit_width > 0 {
                // still try with zero padding
            }
            let slice_end = (pos + byte_len).min(data.len());
            let mut br = LsbBits::new(&data[pos..slice_end]);
            let take = total.min(count - out.len());
            for _ in 0..take { out.push(br.get(bit_width)); }
            pos += byte_len;
        }
    }
    Ok(out)
}

fn decode_levels_v1(data: &[u8], pos: &mut usize, encoding: i32, max_level: u16, count: usize) -> Result<Vec<u16>, String> {
    if max_level == 0 { return Ok(vec![0; count]); }
    let bw = bits_needed(max_level);
    match encoding {
        3 => { // RLE length-prefixed
            if *pos + 4 > data.len() { return Err("levels eof".into()); }
            let len = i32::from_le_bytes(data[*pos..*pos+4].try_into().unwrap());
            if len < 0 { return Err(neg_err()); }
            *pos += 4;
            let len = len as usize;
            let end = (*pos + len).min(data.len());
            let vals = decode_rle_hybrid(&data[*pos..end], bw, count)?;
            *pos += len;
            Ok(vals.into_iter().map(|v| v as u16).collect())
        }
        4 => { // BIT_PACKED deprecated, MSB first
            let byte_len = (count * bw as usize + 7) / 8;
            let end = (*pos + byte_len).min(data.len());
            let mut br = MsbBits::new(&data[*pos..end]);
            let mut out = Vec::with_capacity(count);
            for _ in 0..count { out.push(br.get(bw) as u16); }
            *pos += byte_len;
            Ok(out)
        }
        _ => Err(format!("unsupported levels encoding {}", encoding)),
    }
}

pub fn neg_err() -> String {
    "parquet: File out of specification: Number must be zero or positive: out of range integral type conversion attempted".into()
}
fn wrong_page_size_err() -> String {
    "parquet: File out of specification: The page header reported the wrong page size".into()
}

fn decode_plain(data: &[u8], pos: &mut usize, physical: i32, type_length: i32, count: usize) -> Result<Vec<PhysValue>, String> {
    let mut out = Vec::with_capacity(count);
    match physical {
        0 => {
            let mut br = LsbBits::new(&data[*pos..]);
            for _ in 0..count { out.push(PhysValue::Bool(br.get(1) != 0)); }
            *pos += (count + 7) / 8;
        }
        1 => {
            for _ in 0..count {
                if *pos+4 > data.len() { return Err("plain eof".into()); }
                out.push(PhysValue::I32(i32::from_le_bytes(data[*pos..*pos+4].try_into().unwrap()))); *pos += 4;
            }
        }
        2 => {
            for _ in 0..count {
                if *pos+8 > data.len() { return Err("plain eof".into()); }
                out.push(PhysValue::I64(i64::from_le_bytes(data[*pos..*pos+8].try_into().unwrap()))); *pos += 8;
            }
        }
        3 => {
            for _ in 0..count {
                if *pos+12 > data.len() { return Err("plain eof".into()); }
                let mut b = [0u8;12]; b.copy_from_slice(&data[*pos..*pos+12]);
                out.push(PhysValue::Int96(b)); *pos += 12;
            }
        }
        4 => {
            for _ in 0..count {
                if *pos+4 > data.len() { return Err("plain eof".into()); }
                out.push(PhysValue::F32(f32::from_le_bytes(data[*pos..*pos+4].try_into().unwrap()))); *pos += 4;
            }
        }
        5 => {
            for _ in 0..count {
                if *pos+8 > data.len() { return Err("plain eof".into()); }
                out.push(PhysValue::F64(f64::from_le_bytes(data[*pos..*pos+8].try_into().unwrap()))); *pos += 8;
            }
        }
        6 => {
            for _ in 0..count {
                if *pos+4 > data.len() { return Err("plain eof".into()); }
                let len = i32::from_le_bytes(data[*pos..*pos+4].try_into().unwrap());
                if len < 0 { return Err(neg_err()); }
                *pos += 4;
                let len = len as usize;
                if *pos+len > data.len() { return Err("plain eof".into()); }
                out.push(PhysValue::Bytes(data[*pos..*pos+len].to_vec())); *pos += len;
            }
        }
        7 => {
            let tl = if type_length < 0 { return Err(neg_err()) } else { type_length as usize };
            for _ in 0..count {
                if *pos+tl > data.len() { return Err("plain eof".into()); }
                out.push(PhysValue::Bytes(data[*pos..*pos+tl].to_vec())); *pos += tl;
            }
        }
        _ => return Err(format!("unsupported physical type {}", physical)),
    }
    Ok(out)
}

fn decode_delta_binary_packed(data: &[u8], pos: &mut usize, count: usize, is_i64: bool) -> Result<Vec<i64>, String> {
    if count == 0 { return Ok(vec![]); }
    let block_size = read_uleb(data, pos)? as usize;
    let miniblocks = read_uleb(data, pos)? as usize;
    let _total = read_uleb(data, pos)?;
    let first = read_zigzag(data, pos)?;
    let mut out = vec![first];
    if block_size == 0 || miniblocks == 0 { return Err("delta header".into()); }
    let per_mini = block_size / miniblocks;
    if per_mini == 0 { return Err("delta header".into()); }
    let mut current = first;
    while out.len() < count {
        let min_delta = read_zigzag(data, pos)?;
        if *pos + miniblocks > data.len() { return Err("delta eof".into()); }
        let widths: Vec<u8> = data[*pos..*pos+miniblocks].to_vec();
        *pos += miniblocks;
        for &bw in &widths {
            if out.len() >= count { break; }
            let byte_len = per_mini * bw as usize / 8;
            let end = (*pos + byte_len).min(data.len());
            let mut slice = &data[*pos..end];
            // If the miniblock needs more bytes than present (last block truncated), pad logically via LsbBits zero-fill.
            let owned;
            if end - *pos < byte_len {
                let mut v = slice.to_vec(); v.resize(byte_len, 0); owned = v; slice = &owned;
                let mut br = LsbBits::new(slice);
                for _ in 0..per_mini {
                    if out.len() >= count { break; }
                    let delta = br.get(bw) as i64 + min_delta;
                    current = current.wrapping_add(delta);
                    out.push(current);
                }
                *pos = end;
            } else {
                let mut br = LsbBits::new(slice);
                for _ in 0..per_mini {
                    if out.len() >= count { break; }
                    let delta = br.get(bw) as i64 + min_delta;
                    current = current.wrapping_add(delta);
                    out.push(current);
                }
                *pos += byte_len;
            }
            let _ = is_i64;
        }
    }
    out.truncate(count);
    Ok(out)
}

fn decode_values(data: &[u8], start_pos: usize, encoding: i32, physical: i32, type_length: i32, count: usize, dictionary: Option<&[PhysValue]>) -> Result<Vec<PhysValue>, String> {
    let mut pos = start_pos;
    match encoding {
        0 => decode_plain(data, &mut pos, physical, type_length, count),
        2 => {
            // PLAIN_DICTIONARY: bit width byte, then deprecated bit-packed indices (MSB)
            let dict = dictionary.ok_or("missing dictionary")?;
            if pos >= data.len() { return Err("dict indices eof".into()); }
            let bw = data[pos]; pos += 1;
            let mut br = MsbBits::new(&data[pos..]);
            let mut out = Vec::with_capacity(count);
            for _ in 0..count {
                let idx = br.get(bw) as usize;
                out.push(dict.get(idx).cloned().ok_or("dictionary index out of range")?);
            }
            Ok(out)
        }
        8 => {
            // RLE_DICTIONARY: bit width byte, then RLE hybrid (no length)
            let dict = dictionary.ok_or("missing dictionary")?;
            if pos >= data.len() { return Err("dict indices eof".into()); }
            let bw = data[pos]; pos += 1;
            let idxs = decode_rle_hybrid(&data[pos..], bw, count)?;
            let mut out = Vec::with_capacity(count);
            for idx in idxs {
                out.push(dict.get(idx as usize).cloned().ok_or("dictionary index out of range")?);
            }
            Ok(out)
        }
        3 => {
            // RLE (booleans): 4-byte length prefix then hybrid with bit width 1
            if pos + 4 > data.len() { return Err("rle values eof".into()); }
            let len = i32::from_le_bytes(data[pos..pos+4].try_into().unwrap());
            if len < 0 { return Err(neg_err()); }
            pos += 4;
            let end = (pos + len as usize).min(data.len());
            let vals = decode_rle_hybrid(&data[pos..end], 1, count)?;
            Ok(vals.into_iter().map(|v| PhysValue::Bool(v != 0)).collect())
        }
        4 => {
            // BIT_PACKED deprecated for dictionary indices (MSB). First byte is bit width? 
            // In old files this encoding is used for levels, rarely values. Treat like PLAIN_DICTIONARY if dict present.
            let dict = dictionary.ok_or("missing dictionary")?;
            if pos >= data.len() { return Err("dict indices eof".into()); }
            let bw = data[pos]; pos += 1;
            let mut br = MsbBits::new(&data[pos..]);
            let mut out = Vec::with_capacity(count);
            for _ in 0..count {
                let idx = br.get(bw) as usize;
                out.push(dict.get(idx).cloned().ok_or("dictionary index out of range")?);
            }
            Ok(out)
        }
        5 => {
            let vals = decode_delta_binary_packed(data, &mut pos, count, physical == 2)?;
            Ok(vals.into_iter().map(|v| if physical == 2 { PhysValue::I64(v) } else { PhysValue::I32(v as i32) }).collect())
        }
        6 => {
            // DELTA_LENGTH_BYTE_ARRAY
            let lens = decode_delta_binary_packed(data, &mut pos, count, false)?;
            let mut out = Vec::with_capacity(count);
            for l in lens {
                if l < 0 { return Err(neg_err()); }
                let l = l as usize;
                if pos + l > data.len() { return Err("delta length byte array eof".into()); }
                out.push(PhysValue::Bytes(data[pos..pos+l].to_vec()));
                pos += l;
            }
            Ok(out)
        }
        7 => {
            // DELTA_BYTE_ARRAY
            let prefix_lens = decode_delta_binary_packed(data, &mut pos, count, false)?;
            let suffix_lens = decode_delta_binary_packed(data, &mut pos, count, false)?;
            let mut out: Vec<PhysValue> = Vec::with_capacity(count);
            for i in 0..count {
                let pre = prefix_lens[i]; let suf = suffix_lens[i];
                if pre < 0 || suf < 0 { return Err(neg_err()); }
                let suf = suf as usize; let pre = pre as usize;
                if pos + suf > data.len() { return Err("delta byte array eof".into()); }
                let suffix = data[pos..pos+suf].to_vec(); pos += suf;
                let mut val = Vec::new();
                if pre > 0 {
                    if let Some(PhysValue::Bytes(prev)) = out.last() {
                        let take = pre.min(prev.len());
                        val.extend_from_slice(&prev[..take]);
                        if take < pre { val.resize(pre, 0); }
                    } else { val.resize(pre, 0); }
                }
                val.extend_from_slice(&suffix);
                out.push(PhysValue::Bytes(val));
            }
            Ok(out)
        }
        9 => {
            // BYTE_STREAM_SPLIT
            let w = match physical { 1=>4, 2=>8, 4=>4, 5=>8, 7=> type_length as usize, _=> return Err("byte stream split unsupported type".into()) };
            if w == 0 { return Err("byte stream split width".into()); }
            let total = count * w;
            if pos + total > data.len() { return Err("byte stream split eof".into()); }
            let mut bufs = vec![vec![0u8; w]; count];
            for byte_idx in 0..w {
                for i in 0..count {
                    bufs[i][byte_idx] = data[pos + byte_idx * count + i];
                }
            }
            let mut out = Vec::with_capacity(count);
            for b in bufs {
                out.push(match physical {
                    1 => PhysValue::I32(i32::from_le_bytes(b.clone().try_into().unwrap())),
                    2 => PhysValue::I64(i64::from_le_bytes(b.clone().try_into().unwrap())),
                    4 => PhysValue::F32(f32::from_le_bytes(b.clone().try_into().unwrap())),
                    5 => PhysValue::F64(f64::from_le_bytes(b.clone().try_into().unwrap())),
                    _ => PhysValue::Bytes(b),
                });
            }
            Ok(out)
        }
        _ => Err(format!("unsupported encoding {}", encoding)),
    }
}

/// Walk pages of a column chunk, invoking callback-ish collection.
/// If decode_data, returns cells; always returns page infos.
/// max_def/max_rep are for the leaf.
pub fn read_column(file: &[u8], chunk: &ColumnChunk, physical: i32, type_length: i32, max_def: u16, max_rep: u16, want_pages_only: bool) -> Result<(Vec<Cell>, Vec<PageInfo>), String> {
    let start = chunk.dictionary_page_offset.unwrap_or(chunk.data_page_offset);
    if start < 0 { return Err(neg_err()); }
    let start = start as usize;
    let total = chunk.total_compressed_size;
    if total < 0 { return Err(neg_err()); }
    let total = total as usize;
    if start > file.len() { return Err("parquet: EOF".into()); }
    let chunk_end = (start + total).min(file.len());
    let mut pos = start;
    let mut cells: Vec<Cell> = Vec::new();
    let mut infos: Vec<PageInfo> = Vec::new();
    let mut dictionary: Option<Vec<PhysValue>> = None;
    while pos < chunk_end {
        // Parse page header. Note: limit reader to chunk_end so that a header
        // claiming more than the remaining chunk yields wrong-page-size.
        let mut r = Reader::new(&file[pos..chunk_end]);
        let hdr = match r.parse_struct() {
            Ok(h) => h,
            Err(TError::Eof) => return Err(wrong_page_size_err()),
            Err(TError::Protocol) => return Err("parquet: File out of specification: error parsing page header".into()),
        };
        let hlen = r.pos;
        let page_type = as_int(get(&hdr,1)).ok_or_else(wrong_page_size_err)? as i32;
        let uncomp_size = as_int(get(&hdr,2)).ok_or_else(wrong_page_size_err)?;
        let comp_size = as_int(get(&hdr,3)).ok_or_else(wrong_page_size_err)?;
        if uncomp_size < 0 || comp_size < 0 { return Err(neg_err()); }
        let comp_size = comp_size as usize;
        let uncomp_size_u = uncomp_size as usize;
        if hlen + comp_size > chunk_end - pos {
            return Err(wrong_page_size_err());
        }
        let page_data_start = pos + hlen;
        let page_data = &file[page_data_start..page_data_start+comp_size];
        match page_type {
            2 => { // dictionary
                let dh = as_struct(get(&hdr,7)).cloned().unwrap_or_default();
                let num = as_int(get(&dh,1)).unwrap_or(0);
                if num < 0 { return Err(neg_err()); }
                let enc = as_int(get(&dh,2)).unwrap_or(0) as i32;
                infos.push(PageInfo { page_type, uncompressed_size: uncomp_size, num_values: num, encoding: enc });
                if !want_pages_only {
                    let raw = decompress(chunk.codec, page_data, uncomp_size_u)?;
                    let mut p = 0usize;
                    let vals = decode_plain(&raw, &mut p, physical, type_length, num as usize)?;
                    dictionary = Some(vals);
                }
            }
            0 => { // data page v1
                let dh = as_struct(get(&hdr,5)).cloned().unwrap_or_default();
                let num_values = as_int(get(&dh,1)).unwrap_or(0);
                if num_values < 0 { return Err(neg_err()); }
                let enc = as_int(get(&dh,2)).unwrap_or(0) as i32;
                let def_enc = as_int(get(&dh,3)).unwrap_or(3) as i32;
                let rep_enc = as_int(get(&dh,4)).unwrap_or(3) as i32;
                infos.push(PageInfo { page_type, uncompressed_size: uncomp_size, num_values, encoding: enc });
                if !want_pages_only {
                    let raw = decompress(chunk.codec, page_data, uncomp_size_u)?;
                    let mut p = 0usize;
                    let reps = decode_levels_v1(&raw, &mut p, rep_enc, max_rep, num_values as usize)?;
                    let defs = decode_levels_v1(&raw, &mut p, def_enc, max_def, num_values as usize)?;
                    let nonnull = defs.iter().filter(|&&d| d == max_def).count();
                    let vals = decode_values(&raw, p, enc, physical, type_length, nonnull, dictionary.as_deref())?;
                    let mut vi = vals.into_iter();
                    for i in 0..(num_values as usize) {
                        let d = defs[i];
                        let value = if d == max_def { vi.next() } else { None };
                        cells.push(Cell { rep: reps[i], def: d, value });
                    }
                }
            }
            3 => { // data page v2
                let dh = as_struct(get(&hdr,8)).cloned().unwrap_or_default();
                let num_values = as_int(get(&dh,1)).unwrap_or(0);
                if num_values < 0 { return Err(neg_err()); }
                let _num_nulls = as_int(get(&dh,2)).unwrap_or(0);
                let _num_rows = as_int(get(&dh,3)).unwrap_or(0);
                let enc = as_int(get(&dh,4)).unwrap_or(0) as i32;
                let def_len = as_int(get(&dh,5)).unwrap_or(0);
                let rep_len = as_int(get(&dh,6)).unwrap_or(0);
                if def_len < 0 || rep_len < 0 { return Err(neg_err()); }
                let def_len = def_len as usize; let rep_len = rep_len as usize;
                let is_compressed = as_bool(get(&dh,7)).unwrap_or(true);
                infos.push(PageInfo { page_type, uncompressed_size: uncomp_size, num_values, encoding: enc });
                if !want_pages_only {
                    if rep_len + def_len > page_data.len() { return Err(wrong_page_size_err()); }
                    let rep_data = &page_data[..rep_len];
                    let def_data = &page_data[rep_len..rep_len+def_len];
                    let values_comp = &page_data[rep_len+def_len..];
                    let reps: Vec<u16> = if max_rep == 0 { vec![0; num_values as usize] } else { decode_rle_hybrid(rep_data, bits_needed(max_rep), num_values as usize)?.into_iter().map(|v| v as u16).collect() };
                    let defs: Vec<u16> = if max_def == 0 { vec![0; num_values as usize] } else { decode_rle_hybrid(def_data, bits_needed(max_def), num_values as usize)?.into_iter().map(|v| v as u16).collect() };
                    let values_expected = uncomp_size_u.saturating_sub(rep_len + def_len);
                    let raw_values = if is_compressed && chunk.codec != 0 { decompress(chunk.codec, values_comp, values_expected)? } else { values_comp.to_vec() };
                    let nonnull = defs.iter().filter(|&&d| d == max_def).count();
                    let vals = decode_values(&raw_values, 0, enc, physical, type_length, nonnull, dictionary.as_deref())?;
                    let mut vi = vals.into_iter();
                    for i in 0..(num_values as usize) {
                        let d = defs[i];
                        let value = if d == max_def { vi.next() } else { None };
                        cells.push(Cell { rep: reps[i], def: d, value });
                    }
                }
            }
            1 => {
                infos.push(PageInfo { page_type, uncompressed_size: uncomp_size, num_values: 0, encoding: 0 });
            }
            _ => {
                return Err(format!("parquet: File out of specification: unknown page type {}", page_type));
            }
        }
        pos = page_data_start + comp_size;
    }
    Ok((cells, infos))
}
RS
"}

actions.command:
cat > src/page.rs <<'RS'
use crate::codec::decompress;
use crate::meta::ColumnChunk;
use crate::thrift::*;

#[derive(Debug, Clone, PartialEq)]
pub enum PhysValue {
    Bool(bool),
    I32(i32),
    I64(i64),
    Int96([u8;12]),
    F32(f32),
    F64(f64),
    Bytes(Vec<u8>),
}

#[derive(Debug, Clone)]
pub struct Cell {
    pub rep: u16,
    pub def: u16,
    pub value: Option<PhysValue>,
}

#[derive(Debug, Clone)]
pub struct PageInfo {
    pub page_type: i32,
    pub uncompressed_size: i64,
    pub num_values: i64,
    pub encoding: i32,
}

fn bits_needed(max: u16) -> u8 {
    if max == 0 { 0 } else { 16 - (max as u16).leading_zeros() as u8 }
}

fn read_uleb(data: &[u8], pos: &mut usize) -> Result<u64, String> {
    let mut result: u64 = 0; let mut shift = 0;
    loop {
        let b = *data.get(*pos).ok_or("unexpected eof")?; *pos += 1;
        result |= ((b & 0x7f) as u64) << shift; shift += 7;
        if b & 0x80 == 0 { break; }
        if shift > 70 { return Err("varint too long".into()); }
    }
    Ok(result)
}
fn read_zigzag(data: &[u8], pos: &mut usize) -> Result<i64, String> {
    let n = read_uleb(data, pos)?;
    Ok(((n >> 1) as i64) ^ -((n & 1) as i64))
}

struct LsbBits<'a> { data: &'a [u8], bit_pos: usize }
impl<'a> LsbBits<'a> {
    fn new(data: &'a [u8]) -> Self { Self { data, bit_pos: 0 } }
    fn get(&mut self, n: u8) -> u32 {
        let mut v: u32 = 0;
        for i in 0..n {
            let byte = self.data.get(self.bit_pos / 8).copied().unwrap_or(0);
            let bit = (byte >> (self.bit_pos % 8)) & 1;
            v |= (bit as u32) << i;
            self.bit_pos += 1;
        }
        v
    }
}
struct MsbBits<'a> { data: &'a [u8], bit_pos: usize }
impl<'a> MsbBits<'a> {
    fn new(data: &'a [u8]) -> Self { Self { data, bit_pos: 0 } }
    fn get(&mut self, n: u8) -> u32 {
        let mut v: u32 = 0;
        for _ in 0..n {
            let byte = self.data.get(self.bit_pos / 8).copied().unwrap_or(0);
            let bit = (byte >> (7 - (self.bit_pos % 8))) & 1;
            v = (v << 1) | bit as u32;
            self.bit_pos += 1;
        }
        v
    }
}

pub fn decode_rle_hybrid(data: &[u8], bit_width: u8, count: usize) -> Result<Vec<u32>, String> {
    let mut out = Vec::with_capacity(count);
    let mut pos = 0usize;
    while out.len() < count {
        if pos >= data.len() {
            // Pad with zeros if data ran out (can happen for bit_width 0 rep levels in V2)
            out.resize(count, 0);
            break;
        }
        let header = read_uleb(data, &mut pos)?;
        if header & 1 == 0 {
            let run = (header >> 1) as usize;
            let byte_len = (bit_width as usize + 7) / 8;
            let mut v: u32 = 0;
            for i in 0..byte_len {
                v |= (*data.get(pos+i).ok_or("rle eof")? as u32) << (8*i);
            }
            pos += byte_len;
            let take = run.min(count - out.len());
            out.extend(std::iter::repeat(v).take(take));
        } else {
            let groups = (header >> 1) as usize;
            let total = groups * 8;
            let byte_len = groups * bit_width as usize;
            if pos + byte_len > data.len() && bit_width > 0 {
                // still try with zero padding
            }
            let slice_end = (pos + byte_len).min(data.len());
            let mut br = LsbBits::new(&data[pos..slice_end]);
            let take = total.min(count - out.len());
            for _ in 0..take { out.push(br.get(bit_width)); }
            pos += byte_len;
        }
    }
    Ok(out)
}

fn decode_levels_v1(data: &[u8], pos: &mut usize, encoding: i32, max_level: u16, count: usize) -> Result<Vec<u16>, String> {
    if max_level == 0 { return Ok(vec![0; count]); }
    let bw = bits_needed(max_level);
    match encoding {
        3 => { // RLE length-prefixed
            if *pos + 4 > data.len() { return Err("levels eof".into()); }
            let len = i32::from_le_bytes(data[*pos..*pos+4].try_into().unwrap());
            if len < 0 { return Err(neg_err()); }
            *pos += 4;
            let len = len as usize;
            let end = (*pos + len).min(data.len());
            let vals = decode_rle_hybrid(&data[*pos..end], bw, count)?;
            *pos += len;
            Ok(vals.into_iter().map(|v| v as u16).collect())
        }
        4 => { // BIT_PACKED deprecated, MSB first
            let byte_len = (count * bw as usize + 7) / 8;
            let end = (*pos + byte_len).min(data.len());
            let mut br = MsbBits::new(&data[*pos..end]);
            let mut out = Vec::with_capacity(count);
            for _ in 0..count { out.push(br.get(bw) as u16); }
            *pos += byte_len;
            Ok(out)
        }
        _ => Err(format!("unsupported levels encoding {}", encoding)),
    }
}

pub fn neg_err() -> String {
    "parquet: File out of specification: Number must be zero or positive: out of range integral type conversion attempted".into()
}
fn wrong_page_size_err() -> String {
    "parquet: File out of specification: The page header reported the wrong page size".into()
}

fn decode_plain(data: &[u8], pos: &mut usize, physical: i32, type_length: i32, count: usize) -> Result<Vec<PhysValue>, String> {
    let mut out = Vec::with_capacity(count);
    match physical {
        0 => {
            let mut br = LsbBits::new(&data[*pos..]);
            for _ in 0..count { out.push(PhysValue::Bool(br.get(1) != 0)); }
            *pos += (count + 7) / 8;
        }
        1 => {
            for _ in 0..count {
                if *pos+4 > data.len() { return Err("plain eof".into()); }
                out.push(PhysValue::I32(i32::from_le_bytes(data[*pos..*pos+4].try_into().unwrap()))); *pos += 4;
            }
        }
        2 => {
            for _ in 0..count {
                if *pos+8 > data.len() { return Err("plain eof".into()); }
                out.push(PhysValue::I64(i64::from_le_bytes(data[*pos..*pos+8].try_into().unwrap()))); *pos += 8;
            }
        }
        3 => {
            for _ in 0..count {
                if *pos+12 > data.len() { return Err("plain eof".into()); }
                let mut b = [0u8;12]; b.copy_from_slice(&data[*pos..*pos+12]);
                out.push(PhysValue::Int96(b)); *pos += 12;
            }
        }
        4 => {
            for _ in 0..count {
                if *pos+4 > data.len() { return Err("plain eof".into()); }
                out.push(PhysValue::F32(f32::from_le_bytes(data[*pos..*pos+4].try_into().unwrap()))); *pos += 4;
            }
        }
        5 => {
            for _ in 0..count {
                if *pos+8 > data.len() { return Err("plain eof".into()); }
                out.push(PhysValue::F64(f64::from_le_bytes(data[*pos..*pos+8].try_into().unwrap()))); *pos += 8;
            }
        }
        6 => {
            for _ in 0..count {
                if *pos+4 > data.len() { return Err("plain eof".into()); }
                let len = i32::from_le_bytes(data[*pos..*pos+4].try_into().unwrap());
                if len < 0 { return Err(neg_err()); }
                *pos += 4;
                let len = len as usize;
                if *pos+len > data.len() { return Err("plain eof".into()); }
                out.push(PhysValue::Bytes(data[*pos..*pos+len].to_vec())); *pos += len;
            }
        }
        7 => {
            let tl = if type_length < 0 { return Err(neg_err()) } else { type_length as usize };
            for _ in 0..count {
                if *pos+tl > data.len() { return Err("plain eof".into()); }
                out.push(PhysValue::Bytes(data[*pos..*pos+tl].to_vec())); *pos += tl;
            }
        }
        _ => return Err(format!("unsupported physical type {}", physical)),
    }
    Ok(out)
}

fn decode_delta_binary_packed(data: &[u8], pos: &mut usize, count: usize, is_i64: bool) -> Result<Vec<i64>, String> {
    if count == 0 { return Ok(vec![]); }
    let block_size = read_uleb(data, pos)? as usize;
    let miniblocks = read_uleb(data, pos)? as usize;
    let _total = read_uleb(data, pos)?;
    let first = read_zigzag(data, pos)?;
    let mut out = vec![first];
    if block_size == 0 || miniblocks == 0 { return Err("delta header".into()); }
    let per_mini = block_size / miniblocks;
    if per_mini == 0 { return Err("delta header".into()); }
    let mut current = first;
    while out.len() < count {
        let min_delta = read_zigzag(data, pos)?;
        if *pos + miniblocks > data.len() { return Err("delta eof".into()); }
        let widths: Vec<u8> = data[*pos..*pos+miniblocks].to_vec();
        *pos += miniblocks;
        for &bw in &widths {
            if out.len() >= count { break; }
            let byte_len = per_mini * bw as usize / 8;
            let end = (*pos + byte_len).min(data.len());
            let mut slice = &data[*pos..end];
            // If the miniblock needs more bytes than present (last block truncated), pad logically via LsbBits zero-fill.
            let owned;
            if end - *pos < byte_len {
                let mut v = slice.to_vec(); v.resize(byte_len, 0); owned = v; slice = &owned;
                let mut br = LsbBits::new(slice);
                for _ in 0..per_mini {
                    if out.len() >= count { break; }
                    let delta = br.get(bw) as i64 + min_delta;
                    current = current.wrapping_add(delta);
                    out.push(current);
                }
                *pos = end;
            } else {
                let mut br = LsbBits::new(slice);
                for _ in 0..per_mini {
                    if out.len() >= count { break; }
                    let delta = br.get(bw) as i64 + min_delta;
                    current = current.wrapping_add(delta);
                    out.push(current);
                }
                *pos += byte_len;
            }
            let _ = is_i64;
        }
    }
    out.truncate(count);
    Ok(out)
}

fn decode_values(data: &[u8], start_pos: usize, encoding: i32, physical: i32, type_length: i32, count: usize, dictionary: Option<&[PhysValue]>) -> Result<Vec<PhysValue>, String> {
    let mut pos = start_pos;
    match encoding {
        0 => decode_plain(data, &mut pos, physical, type_length, count),
        2 => {
            // PLAIN_DICTIONARY: bit width byte, then deprecated bit-packed indices (MSB)
            let dict = dictionary.ok_or("missing dictionary")?;
            if pos >= data.len() { return Err("dict indices eof".into()); }
            let bw = data[pos]; pos += 1;
            let mut br = MsbBits::new(&data[pos..]);
            let mut out = Vec::with_capacity(count);
            for _ in 0..count {
                let idx = br.get(bw) as usize;
                out.push(dict.get(idx).cloned().ok_or("dictionary index out of range")?);
            }
            Ok(out)
        }
        8 => {
            // RLE_DICTIONARY: bit width byte, then RLE hybrid (no length)
            let dict = dictionary.ok_or("missing dictionary")?;
            if pos >= data.len() { return Err("dict indices eof".into()); }
            let bw = data[pos]; pos += 1;
            let idxs = decode_rle_hybrid(&data[pos..], bw, count)?;
            let mut out = Vec::with_capacity(count);
            for idx in idxs {
                out.push(dict.get(idx as usize).cloned().ok_or("dictionary index out of range")?);
            }
            Ok(out)
        }
        3 => {
            // RLE (booleans): 4-byte length prefix then hybrid with bit width 1
            if pos + 4 > data.len() { return Err("rle values eof".into()); }
            let len = i32::from_le_bytes(data[pos..pos+4].try_into().unwrap());
            if len < 0 { return Err(neg_err()); }
            pos += 4;
            let end = (pos + len as usize).min(data.len());
            let vals = decode_rle_hybrid(&data[pos..end], 1, count)?;
            Ok(vals.into_iter().map(|v| PhysValue::Bool(v != 0)).collect())
        }
        4 => {
            // BIT_PACKED deprecated for dictionary indices (MSB). First byte is bit width? 
            // In old files this encoding is used for levels, rarely values. Treat like PLAIN_DICTIONARY if dict present.
            let dict = dictionary.ok_or("missing dictionary")?;
            if pos >= data.len() { return Err("dict indices eof".into()); }
            let bw = data[pos]; pos += 1;
            let mut br = MsbBits::new(&data[pos..]);
            let mut out = Vec::with_capacity(count);
            for _ in 0..count {
                let idx = br.get(bw) as usize;
                out.push(dict.get(idx).cloned().ok_or("dictionary index out of range")?);
            }
            Ok(out)
        }
        5 => {
            let vals = decode_delta_binary_packed(data, &mut pos, count, physical == 2)?;
            Ok(vals.into_iter().map(|v| if physical == 2 { PhysValue::I64(v) } else { PhysValue::I32(v as i32) }).collect())
        }
        6 => {
            // DELTA_LENGTH_BYTE_ARRAY
            let lens = decode_delta_binary_packed(data, &mut pos, count, false)?;
            let mut out = Vec::with_capacity(count);
            for l in lens {
                if l < 0 { return Err(neg_err()); }
                let l = l as usize;
                if pos + l > data.len() { return Err("delta length byte array eof".into()); }
                out.push(PhysValue::Bytes(data[pos..pos+l].to_vec()));
                pos += l;
            }
            Ok(out)
        }
        7 => {
            // DELTA_BYTE_ARRAY
            let prefix_lens = decode_delta_binary_packed(data, &mut pos, count, false)?;
            let suffix_lens = decode_delta_binary_packed(data, &mut pos, count, false)?;
            let mut out: Vec<PhysValue> = Vec::with_capacity(count);
            for i in 0..count {
                let pre = prefix_lens[i]; let suf = suffix_lens[i];
                if pre < 0 || suf < 0 { return Err(neg_err()); }
                let suf = suf as usize; let pre = pre as usize;
                if pos + suf > data.len() { return Err("delta byte array eof".into()); }
                let suffix = data[pos..pos+suf].to_vec(); pos += suf;
                let mut val = Vec::new();
                if pre > 0 {
                    if let Some(PhysValue::Bytes(prev)) = out.last() {
                        let take = pre.min(prev.len());
                        val.extend_from_slice(&prev[..take]);
                        if take < pre { val.resize(pre, 0); }
                    } else { val.resize(pre, 0); }
                }
                val.extend_from_slice(&suffix);
                out.push(PhysValue::Bytes(val));
            }
            Ok(out)
        }
        9 => {
            // BYTE_STREAM_SPLIT
            let w = match physical { 1=>4, 2=>8, 4=>4, 5=>8, 7=> type_length as usize, _=> return Err("byte stream split unsupported type".into()) };
            if w == 0 { return Err("byte stream split width".into()); }
            let total = count * w;
            if pos + total > data.len() { return Err("byte stream split eof".into()); }
            let mut bufs = vec![vec![0u8; w]; count];
            for byte_idx in 0..w {
                for i in 0..count {
                    bufs[i][byte_idx] = data[pos + byte_idx * count + i];
                }
            }
            let mut out = Vec::with_capacity(count);
            for b in bufs {
                out.push(match physical {
                    1 => PhysValue::I32(i32::from_le_bytes(b.clone().try_into().unwrap())),
                    2 => PhysValue::I64(i64::from_le_bytes(b.clone().try_into().unwrap())),
                    4 => PhysValue::F32(f32::from_le_bytes(b.clone().try_into().unwrap())),
                    5 => PhysValue::F64(f64::from_le_bytes(b.clone().try_into().unwrap())),
                    _ => PhysValue::Bytes(b),
                });
            }
            Ok(out)
        }
        _ => Err(format!("unsupported encoding {}", encoding)),
    }
}

/// Walk pages of a column chunk, invoking callback-ish collection.
/// If decode_data, returns cells; always returns page infos.
/// max_def/max_rep are for the leaf.
pub fn read_column(file: &[u8], chunk: &ColumnChunk, physical: i32, type_length: i32, max_def: u16, max_rep: u16, want_pages_only: bool) -> Result<(Vec<Cell>, Vec<PageInfo>), String> {
    let start = chunk.dictionary_page_offset.unwrap_or(chunk.data_page_offset);
    if start < 0 { return Err(neg_err()); }
    let start = start as usize;
    let total = chunk.total_compressed_size;
    if total < 0 { return Err(neg_err()); }
    let total = total as usize;
    if start > file.len() { return Err("parquet: EOF".into()); }
    let chunk_end = (start + total).min(file.len());
    let mut pos = start;
    let mut cells: Vec<Cell> = Vec::new();
    let mut infos: Vec<PageInfo> = Vec::new();
    let mut dictionary: Option<Vec<PhysValue>> = None;
    while pos < chunk_end {
        // Parse page header. Note: limit reader to chunk_end so that a header
        // claiming more than the remaining chunk yields wrong-page-size.
        let mut r = Reader::new(&file[pos..chunk_end]);
        let hdr = match r.parse_struct() {
            Ok(h) => h,
            Err(TError::Eof) => return Err(wrong_page_size_err()),
            Err(TError::Protocol) => return Err("parquet: File out of specification: error parsing page header".into()),
        };
        let hlen = r.pos;
        let page_type = as_int(get(&hdr,1)).ok_or_else(wrong_page_size_err)? as i32;
        let uncomp_size = as_int(get(&hdr,2)).ok_or_else(wrong_page_size_err)?;
        let comp_size = as_int(get(&hdr,3)).ok_or_else(wrong_page_size_err)?;
        if uncomp_size < 0 || comp_size < 0 { return Err(neg_err()); }
        let comp_size = comp_size as usize;
        let uncomp_size_u = uncomp_size as usize;
        if hlen + comp_size > chunk_end - pos {
            return Err(wrong_page_size_err());
        }
        let page_data_start = pos + hlen;
        let page_data = &file[page_data_start..page_data_start+comp_size];
        match page_type {
            2 => { // dictionary
                let dh = as_struct(get(&hdr,7)).cloned().unwrap_or_default();
                let num = as_int(get(&dh,1)).unwrap_or(0);
                if num < 0 { return Err(neg_err()); }
                let enc = as_int(get(&dh,2)).unwrap_or(0) as i32;
                infos.push(PageInfo { page_type, uncompressed_size: uncomp_size, num_values: num, encoding: enc });
                if !want_pages_only {
                    let raw = decompress(chunk.codec, page_data, uncomp_size_u)?;
                    let mut p = 0usize;
                    let vals = decode_plain(&raw, &mut p, physical, type_length, num as usize)?;
                    dictionary = Some(vals);
                }
            }
            0 => { // data page v1
                let dh = as_struct(get(&hdr,5)).cloned().unwrap_or_default();
                let num_values = as_int(get(&dh,1)).unwrap_or(0);
                if num_values < 0 { return Err(neg_err()); }
                let enc = as_int(get(&dh,2)).unwrap_or(0) as i32;
                let def_enc = as_int(get(&dh,3)).unwrap_or(3) as i32;
                let rep_enc = as_int(get(&dh,4)).unwrap_or(3) as i32;
                infos.push(PageInfo { page_type, uncompressed_size: uncomp_size, num_values, encoding: enc });
                if !want_pages_only {
                    let raw = decompress(chunk.codec, page_data, uncomp_size_u)?;
                    let mut p = 0usize;
                    let reps = decode_levels_v1(&raw, &mut p, rep_enc, max_rep, num_values as usize)?;
                    let defs = decode_levels_v1(&raw, &mut p, def_enc, max_def, num_values as usize)?;
                    let nonnull = defs.iter().filter(|&&d| d == max_def).count();
                    let vals = decode_values(&raw, p, enc, physical, type_length, nonnull, dictionary.as_deref())?;
                    let mut vi = vals.into_iter();
                    for i in 0..(num_values as usize) {
                        let d = defs[i];
                        let value = if d == max_def { vi.next() } else { None };
                        cells.push(Cell { rep: reps[i], def: d, value });
                    }
                }
            }
            3 => { // data page v2
                let dh = as_struct(get(&hdr,8)).cloned().unwrap_or_default();
                let num_values = as_int(get(&dh,1)).unwrap_or(0);
                if num_values < 0 { return Err(neg_err()); }
                let _num_nulls = as_int(get(&dh,2)).unwrap_or(0);
                let _num_rows = as_int(get(&dh,3)).unwrap_or(0);
                let enc = as_int(get(&dh,4)).unwrap_or(0) as i32;
                let def_len = as_int(get(&dh,5)).unwrap_or(0);
                let rep_len = as_int(get(&dh,6)).unwrap_or(0);
                if def_len < 0 || rep_len < 0 { return Err(neg_err()); }
                let def_len = def_len as usize; let rep_len = rep_len as usize;
                let is_compressed = as_bool(get(&dh,7)).unwrap_or(true);
                infos.push(PageInfo { page_type, uncompressed_size: uncomp_size, num_values, encoding: enc });
                if !want_pages_only {
                    if rep_len + def_len > page_data.len() { return Err(wrong_page_size_err()); }
                    let rep_data = &page_data[..rep_len];
                    let def_data = &page_data[rep_len..rep_len+def_len];
                    let values_comp = &page_data[rep_len+def_len..];
                    let reps: Vec<u16> = if max_rep == 0 { vec![0; num_values as usize] } else { decode_rle_hybrid(rep_data, bits_needed(max_rep), num_values as usize)?.into_iter().map(|v| v as u16).collect() };
                    let defs: Vec<u16> = if max_def == 0 { vec![0; num_values as usize] } else { decode_rle_hybrid(def_data, bits_needed(max_def), num_values as usize)?.into_iter().map(|v| v as u16).collect() };
                    let values_expected = uncomp_size_u.saturating_sub(rep_len + def_len);
                    let raw_values = if is_compressed && chunk.codec != 0 { decompress(chunk.codec, values_comp, values_expected)? } else { values_comp.to_vec() };
                    let nonnull = defs.iter().filter(|&&d| d == max_def).count();
                    let vals = decode_values(&raw_values, 0, enc, physical, type_length, nonnull, dictionary.as_deref())?;
                    let mut vi = vals.into_iter();
                    for i in 0..(num_values as usize) {
                        let d = defs[i];
                        let value = if d == max_def { vi.next() } else { None };
                        cells.push(Cell { rep: reps[i], def: d, value });
                    }
                }
            }
            1 => {
                infos.push(PageInfo { page_type, uncompressed_size: uncomp_size, num_values: 0, encoding: 0 });
            }
            _ => {
                return Err(format!("parquet: File out of specification: unknown page type {}", page_type));
            }
        }
        pos = page_data_start + comp_size;
    }
    Ok((cells, infos))
}
