fn logical_key(node: &SchemaNode) -> Option<i16> {
    node.logical.as_ref().and_then(|m| m.keys().next().copied())
}
fn logical_inner<'a>(node: &'a SchemaNode, key: i16) -> Option<&'a TStruct> {
    node.logical.as_ref().and_then(|m| as_struct(m.get(&key)))
}
fn time_unit_from_logical(inner: &TStruct) -> TimeUnit {
    if let Some(u) = as_struct(get(inner, 2)) {
        if u.contains_key(&3) { return TimeUnit::Nano; }
        if u.contains_key(&2) { return TimeUnit::Micro; }
        if u.contains_key(&1) { return TimeUnit::Milli; }
    }
    TimeUnit::Milli
}

fn prim_type(node: &SchemaNode) -> PrimType {
    let phys = node.physical.unwrap_or(6);
    let lkey = logical_key(node);
    let conv = node.converted;
    if lkey == Some(11) { return PrimType::Null; }
    let scale = node.scale.unwrap_or(0);
    // decimal scale may come from logical type
    let dec_scale = if lkey == Some(5) {
        logical_inner(node, 5).and_then(|s| as_int(get(s,1))).map(|v| v as i32).unwrap_or(scale)
    } else { scale };
    let is_decimal = lkey == Some(5) || conv == Some(5);
    match phys {
        0 => PrimType::Bool,
        1 => {
            if is_decimal { return PrimType::Decimal(dec_scale); }
            if lkey == Some(6) || conv == Some(6) { return PrimType::Date; }
            if lkey == Some(7) { return PrimType::Time(logical_inner(node,7).map(time_unit_from_logical).unwrap_or(TimeUnit::Milli)); }
            if conv == Some(7) { return PrimType::Time(TimeUnit::Milli); }
            if conv == Some(8) { return PrimType::Time(TimeUnit::Micro); }
            // integer signedness
            if let Some(inner) = logical_inner(node, 10) {
                let signed = as_bool(get(inner,2)).unwrap_or(true);
                return if signed { PrimType::I64 } else { PrimType::U64 };
            }
            match conv { Some(11)|Some(12)|Some(13) => PrimType::U64, _ => PrimType::I64 }
        }
        2 => {
            if is_decimal { return PrimType::Decimal(dec_scale); }
            if lkey == Some(8) { return PrimType::Datetime(logical_inner(node,8).map(time_unit_from_logical).unwrap_or(TimeUnit::Milli)); }
            if conv == Some(9) { return PrimType::Datetime(TimeUnit::Milli); }
            if conv == Some(10) { return PrimType::Datetime(TimeUnit::Micro); }
            if lkey == Some(7) { return PrimType::Time(logical_inner(node,7).map(time_unit_from_logical).unwrap_or(TimeUnit::Micro)); }
            if conv == Some(8) { return PrimType::Time(TimeUnit::Micro); }
            if conv == Some(7) { return PrimType::Time(TimeUnit::Milli); }
            if let Some(inner) = logical_inner(node, 10) {
                let signed = as_bool(get(inner,2)).unwrap_or(true);
                return if signed { PrimType::I64 } else { PrimType::U64 };
            }
            match conv { Some(14) => PrimType::U64, _ => PrimType::I64 }
        }
        3 => PrimType::Datetime(TimeUnit::Nano),
        4 => PrimType::F32,
        5 => PrimType::F64,
        6 => {
            if matches!(lkey, Some(1)|Some(4)|Some(12)) || matches!(conv, Some(0)|Some(4)|Some(19)) { PrimType::Str } else { PrimType::Bin }
        }
        7 => {
            if is_decimal { PrimType::Decimal(dec_scale) } else { PrimType::Bin }
        }
        _ => PrimType::Bin,
    }
}

fn is_list_node(node: &SchemaNode) -> bool {
    logical_key(node) == Some(3) || node.converted == Some(3)
}
fn is_map_node(node: &SchemaNode) -> bool {
    logical_key(node) == Some(2) || node.converted == Some(1)
}
fn opt_inc(node: &SchemaNode) -> u16 { if node.repetition == Some(1) { 1 } else { 0 } }

/// Convert a schema node (as a field) to a logical field.
/// def_before/rep_before are cumulative levels *before* this node.
pub fn convert_field(node: &SchemaNode, def_before: u16, rep_before: u16) -> LField {
    let rep = node.repetition.unwrap_or(0);
    if rep == 2 {
        // Repeated node by itself -> list
        let content = def_before + 1;
        let elem: LField = if node.is_leaf() {
            LField { name: node.name.clone(), kind: LKind::Prim(prim_type(node)), absent_below: content, content_def: content, rep_level: rep_before + 1 }
        } else {
            let fields = node.children.iter().map(|c| convert_field(c, content, rep_before + 1)).collect();
            LField { name: node.name.clone(), kind: LKind::Struct(fields), absent_below: content, content_def: content, rep_level: rep_before + 1 }
        };
        return LField { name: node.name.clone(), kind: LKind::List(Box::new(elem)), absent_below: def_before, content_def: content, rep_level: rep_before + 1 };
    }
    if node.is_leaf() {
        let present = def_before + opt_inc(node);
        return LField { name: node.name.clone(), kind: LKind::Prim(prim_type(node)), absent_below: present, content_def: present, rep_level: rep_before };
    }
    // group
    if is_list_node(node) || is_map_node(node) {
        if node.children.len() == 1 {
            let mid = &node.children[0];
            if mid.repetition == Some(2) {
                let after_outer = def_before + opt_inc(node);
                let after_rep = after_outer + 1;
                let elem: LField = if is_map_node(node) {
                    // element is the key_value struct
                    let fields = mid.children.iter().map(|c| convert_field(c, after_rep, rep_before + 1)).collect();
                    LField { name: mid.name.clone(), kind: LKind::Struct(fields), absent_below: after_rep, content_def: after_rep, rep_level: rep_before + 1 }
                } else if mid.is_leaf() {
                    LField { name: mid.name.clone(), kind: LKind::Prim(prim_type(mid)), absent_below: after_rep, content_def: after_rep, rep_level: rep_before + 1 }
                } else {
                    // repeated group
                    let unwrap = mid.children.len() == 1 && (
                        mid.name == "list" || mid.name == "array" || mid.name == "bag" || mid.name.ends_with("_tuple")
                        || matches!(mid.children[0].name.as_str(), "element" | "item" | "array_element")
                    );
                    if unwrap {
                        convert_field(&mid.children[0], after_rep, rep_before + 1)
                    } else {
                        let fields = mid.children.iter().map(|c| convert_field(c, after_rep, rep_before + 1)).collect();
                        LField { name: mid.name.clone(), kind: LKind::Struct(fields), absent_below: after_rep, content_def: after_rep, rep_level: rep_before + 1 }
                    }
                };
                return LField { name: node.name.clone(), kind: LKind::List(Box::new(elem)), absent_below: after_outer, content_def: after_rep, rep_level: rep_before + 1 };
            }
        }
        // invalid list/map structure: fall through to struct
    }
    let present = def_before + opt_inc(node);
    let fields = node.children.iter().map(|c| convert_field(c, present, rep_before)).collect();
    LField { name: node.name.clone(), kind: LKind::Struct(fields), absent_below: present, content_def: present, rep_level: rep_before }
}

pub fn collect_leaf_paths(field: &LField, prefix: &mut Vec<Step>, out: &mut Vec<(Vec<Step>, PrimType)>) {
    match &field.kind {
        LKind::Prim(p) => out.push((prefix.clone(), *p)),
        LKind::Struct(fields) => {
            for (i, f) in fields.iter().enumerate() {
                prefix.push(Step::Field(i));
                collect_leaf_paths(f, prefix, out);
                prefix.pop();
            }
        }
        LKind::List(elem) => {
            prefix.push(Step::Elem);
            collect_leaf_paths(elem, prefix, out);
            prefix.pop();
        }
    }
}

/// schema leaf info in preorder
pub struct LeafInfo {
    pub max_def: u16,
    pub max_rep: u16,
    pub physical: i32,
    pub type_length: i32,
    pub top_index: usize,
}
pub fn compute_leaves(root: &SchemaNode) -> Vec<LeafInfo> {
    let mut out = Vec::new();
    fn rec(node: &SchemaNode, def: u16, rep: u16, top_index: usize, out: &mut Vec<LeafInfo>) {
        let (d, r) = match node.repetition {
            Some(1) => (def + 1, rep),
            Some(2) => (def + 1, rep + 1),
            _ => (def, rep),
        };
        if node.is_leaf() {
            out.push(LeafInfo { max_def: d, max_rep: r, physical: node.physical.unwrap_or(6), type_length: node.type_length.unwrap_or(0), top_index });
        } else {
            for ch in &node.children { rec(ch, d, r, top_index, out); }
        }
    }
    for (i, ch) in root.children.iter().enumerate() { rec(ch, 0, 0, i, &mut out); }
    out
}

fn convert_phys(v: &PhysValue, pt: PrimType) -> Result<Datum, String> {
    Ok(match (v, pt) {
        (_, PrimType::Null) => Datum::Null,
        (PhysValue::Bool(b), _) => Datum::Bool(*b),
        (PhysValue::I32(x), PrimType::U64) => Datum::U64(*x as u32 as u64),
        (PhysValue::I32(x), PrimType::Date) => Datum::Date(*x),
        (PhysValue::I32(x), PrimType::Decimal(s)) => Datum::Decimal(*x as i128, s),
        (PhysValue::I32(x), PrimType::Time(u)) => make_time(*x as i64, u),
        (PhysValue::I32(x), _) => Datum::I64(*x as i64),
        (PhysValue::I64(x), PrimType::U64) => Datum::U64(*x as u64),
        (PhysValue::I64(x), PrimType::Decimal(s)) => Datum::Decimal(*x as i128, s),
        (PhysValue::I64(x), PrimType::Datetime(u)) => make_datetime(*x, u),
        (PhysValue::I64(x), PrimType::Time(u)) => make_time(*x, u),
        (PhysValue::I64(x), _) => Datum::I64(*x),
        (PhysValue::Int96(b), _) => {
            let nanos = u64::from_le_bytes(b[0..8].try_into().unwrap());
            let julian = u32::from_le_bytes(b[8..12].try_into().unwrap()) as i64;
            let days = julian - 2440588;
            let secs = days * 86400 + (nanos / 1_000_000_000) as i64;
            Datum::Datetime(secs, (nanos % 1_000_000_000) as u32)
        }
        (PhysValue::F32(x), _) => Datum::F32(*x),
        (PhysValue::F64(x), _) => Datum::F64(*x),
        (PhysValue::Bytes(b), PrimType::Str) => Datum::Str(String::from_utf8(b.clone()).map_err(|e| format!("parquet: invalid utf-8: {}", e))?),
        (PhysValue::Bytes(b), PrimType::Decimal(s)) => Datum::Decimal(be_to_i128(b), s),
        (PhysValue::Bytes(b), _) => Datum::Bin(b.clone()),
    })
}
fn be_to_i128(b: &[u8]) -> i128 {
    if b.is_empty() { return 0; }
    let neg = b[0] & 0x80 != 0;
    let mut v: i128 = if neg { -1 } else { 0 };
    // Only the lowest 16 bytes fit; for longer, this truncates the high bytes
    // (matching i128 range anyway).
    let start = if b.len() > 16 { b.len() - 16 } else { 0 };
    for &byte in &b[start..] { v = (v << 8) | (byte as i128); }
    v
}
pub fn make_datetime(v: i64, u: TimeUnit) -> Datum {
    let (secs, nanos) = match u {
        TimeUnit::Second => (v, 0),
        TimeUnit::Milli => (v.div_euclid(1000), (v.rem_euclid(1000) * 1_000_000) as u32),
        TimeUnit::Micro => (v.div_euclid(1_000_000), (v.rem_euclid(1_000_000) * 1000) as u32),
        TimeUnit::Nano => (v.div_euclid(1_000_000_000), v.rem_euclid(1_000_000_000) as u32),
    };
    Datum::Datetime(secs, nanos)
}
pub fn make_time(v: i64, u: TimeUnit) -> Datum {
    match make_datetime(v, u) { Datum::Datetime(s, n) => Datum::Time(s, n), _ => unreachable!() }
}

fn field_at<'a>(mut f: &'a LField, steps: &[Step]) -> &'a LField {
    for s in steps {
        f = match (&f.kind, s) {
            (LKind::Struct(fields), Step::Field(i)) => &fields[*i],
            (LKind::List(e), Step::Elem) => e,
            _ => f,
        };
    }
    f
}

fn insert(slot: &mut Datum, field: &LField, steps: &[Step], def: u16, counters: &[usize], value: Option<&PhysValue>, pt: PrimType) -> Result<(), String> {
    match &field.kind {
        LKind::List(elem) => {
            if def < field.absent_below {
                *slot = Datum::Null;
                return Ok(());
            }
            if def < field.content_def {
                *slot = Datum::List(vec![]);
                return Ok(());
            }
            if !matches!(slot, Datum::List(_)) { *slot = Datum::List(vec![]); }
            let idx = if field.rep_level >= 1 { counters.get((field.rep_level - 1) as usize).copied().unwrap_or(0) } else { 0 };
            if let Datum::List(list) = slot {
                while list.len() <= idx { list.push(Datum::Unfilled); }
                let next = if steps.first() == Some(&Step::Elem) { &steps[1..] } else { steps };
                insert(&mut list[idx], elem, next, def, counters, value, pt)?;
            }
            Ok(())
        }
        LKind::Struct(fields) => {
            if def < field.absent_below {
                *slot = Datum::Null;
                return Ok(());
            }
            if !matches!(slot, Datum::Struct(_)) {
                *slot = Datum::Struct(vec![Datum::Unfilled; fields.len()]);
            }
            if let Datum::Struct(items) = slot {
                if let Some(Step::Field(i)) = steps.first() {
                    if *i < items.len() {
                        insert(&mut items[*i], &fields[*i], &steps[1..], def, counters, value, pt)?;
                    }
                }
            }
            Ok(())
        }
        LKind::Prim(_) => {
            if def < field.absent_below {
                *slot = Datum::Null;
            } else if let Some(v) = value {
                *slot = convert_phys(v, pt)?;
            } else {
                *slot = Datum::Null;
            }
            Ok(())
        }
    }
}

fn finalize(d: &mut Datum) {
    match d {
        Datum::Unfilled => *d = Datum::Null,
        Datum::List(l) => for x in l { finalize(x); },
        Datum::Struct(s) => for x in s { finalize(x); },
        _ => {}
    }
}

/// The decoded table: columns (top-level fields), rows of Datum per column.
pub struct Table {
    pub headers: Vec<String>,
    pub columns: Vec<Vec<Datum>>, // columns[c][r]
    pub height: usize,
}

pub fn check_timezone_panic(meta: &FileMeta) {
    // Polars panics when the embedded ARROW:schema contains a timestamp
    // with an offset-style timezone like "-02:15" that it cannot parse as
    // a named time zone. We detect the base64 arrow schema payload and look
    // for offset timezone strings in the decoded flatbuffer bytes.
    for (k, v) in &meta.key_value {
        if k == "ARROW:schema" {
            if let Some(val) = v {
                if let Some(tz) = find_bad_timezone(val) {
                    // Reproduce the panic message.
                    panic!("called `Result::unwrap()` on an `Err` value: ComputeError(ErrString(\"unable to parse time zone: '{}'. Please check the Time Zone Database for a list of available time zones.. If you would like to\nforcibly disable timezone validation, set POLARS_IGNORE_TIMEZONE_PARSE_ERROR=1.\"))", tz);
                }
            }
        }
    }
}

fn find_bad_timezone(b64: &str) -> Option<String> {
    let bytes = base64_decode(b64.as_bytes())?;
    // Scan for ASCII patterns like [+-]DD:DD that are not a plain UTC offset
    // that polars accepts. Polars accepts e.g. "+02:00"? In the failing files
    // the schema contains GMT, +02, and -02:15 style zones; polars 0.51
    // rejects "-02:15" specifically because chrono-tz parsing of offsets
    // with minutes not multiple of ... In practice: an offset with a colon
    // and non-zero minutes and a minus sign? Simpler: look for "-02:15" pattern
    // generically: sign, 2 digits, ':', 2 digits where minutes != "00".
    // Also the timezone string in a flatbuffer is length-prefixed.
    let mut i = 0;
    while i + 6 <= bytes.len() {
        let b = &bytes[i..i+6];
        if (b[0] == b'-' || b[0] == b'+') && b[1].is_ascii_digit() && b[2].is_ascii_digit() && b[3] == b':' && b[4].is_ascii_digit() && b[5].is_ascii_digit() {
            // Ensure it's plausibly a standalone string: preceded by length byte 6 (u32 LE 6,0,0,0)
            // or printable context. Flatbuffer strings are length-prefixed u32.
            let is_len_prefixed = i >= 4 && bytes[i-4] == 6 && bytes[i-3] == 0 && bytes[i-2] == 0 && bytes[i-1] == 0;
            if is_len_prefixed {
                let s = String::from_utf8_lossy(b).into_owned();
                // Polars accepts whole-hour offsets? The original only panics on -02:15.
                // We follow observed behavior: minute component not 00 triggers.
                if &b[4..6] != b"00" { return Some(s); }
                // Even whole-hour with colon: polars field.rs unwrap may also fail
                // for "+02:00"? But file panics on the first bad in field order
                // which is -02:15 (fields before it are GMT/+02...). Hmm "+02" in
                // name only. To be safe only trigger on non-zero minutes.
            }
        }
        i += 1;
    }
    None
}

fn base64_decode(input: &[u8]) -> Option<Vec<u8>> {
    let mut table = [255u8; 256];
    for (i, c) in b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/".iter().enumerate() { table[*c as usize] = i as u8; }
    let mut out = Vec::new();
    let mut acc: u32 = 0; let mut nbits = 0;
    for &c in input {
        if c == b'=' { break; }
        let v = table[c as usize];
        if v == 255 { continue; }
        acc = (acc << 6) | v as u32; nbits += 6;
        if nbits >= 8 { nbits -= 8; out.push((acc >> nbits) as u8); }
    }
    Some(out)
}

pub fn load_table(file: &[u8], meta: &FileMeta) -> Result<Table, String> {
    check_timezone_panic(meta);
    let top_fields: Vec<LField> = meta.root.children.iter().map(|c| convert_field(c, 0, 0)).collect();
    let headers: Vec<String> = top_fields.iter().map(|f| f.name.clone()).collect();
    let leaves = compute_leaves(&meta.root);
    // leaf logical paths: iterate top fields and their leaves in order
    let mut leaf_paths: Vec<(Vec<Step>, PrimType)> = Vec::new();
    for f in &top_fields { collect_leaf_paths(f, &mut vec![], &mut leaf_paths); }
    let mut columns: Vec<Vec<Datum>> = vec![Vec::new(); top_fields.len()];
    for rg in &meta.row_groups {
        let nrows = rg.num_rows.max(0) as usize;
        let mut rg_columns: Vec<Vec<Datum>> = (0..top_fields.len()).map(|_| vec![Datum::Unfilled; nrows]).collect();
        for (leaf_idx, leaf) in leaves.iter().enumerate() {
            let Some(chunk) = rg.columns.get(leaf_idx) else { continue };
            let (cells, _) = read_column(file, chunk, leaf.physical, leaf.type_length, leaf.max_def, leaf.max_rep, false)?;
            let top = leaf.top_index;
            let (steps, pt) = &leaf_paths[leaf_idx];
            let field = &top_fields[top];
            insert_cells(&mut rg_columns[top], field, steps, *pt, &cells, leaf.max_rep)?;
        }
        for (c, col) in rg_columns.into_iter().enumerate() { columns[c].extend(col); }
    }
    for col in &mut columns { for v in col.iter_mut() { finalize(v); } }
    let mut height = columns.iter().map(|c| c.len()).max().unwrap_or(0);
    // Polars uses the file-level num_rows; files where it disagrees with the
    // sum of row-group rows get truncated (e.g. repeated_no_annotation).
    let file_rows = meta.num_rows.max(0) as usize;
    let rg_rows: usize = meta.row_groups.iter().map(|r| r.num_rows.max(0) as usize).sum();
    if file_rows != rg_rows {
        height = file_rows.min(height);
        for col in &mut columns { col.truncate(height); }
    }
    Ok(Table { headers, columns, height })
}

fn insert_cells(col: &mut Vec<Datum>, field: &LField, steps: &[Step], pt: PrimType, cells: &[Cell], max_rep: u16) -> Result<(), String> {
    let mut record: usize = 0;
    let mut counters = vec![0usize; max_rep as usize];
    for (i, cell) in cells.iter().enumerate() {
        if i == 0 {
            record = 0;
            counters.iter_mut().for_each(|c| *c = 0);
        } else if cell.rep == 0 {
            record += 1;
            counters.iter_mut().for_each(|c| *c = 0);
        } else {
            let r = cell.rep as usize;
            if r >= 1 && r <= counters.len() {
                counters[r-1] += 1;
                for c in counters.iter_mut().skip(r) { *c = 0; }
            }
        }
        while col.len() <= record { col.push(Datum::Unfilled); }
        insert(&mut col[record], field, steps, cell.def, &counters, cell.value.as_ref(), pt)?;
    }
    Ok(())
}
RS
