    s.push('"');
    s
}

pub fn civil_from_days(z: i64) -> (i64, u32, u32) {
    // Howard Hinnant's algorithm, days since 1970-01-01
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097; // [0, 146096]
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365; // [0,399]
    let y = yoe + era * 400;
    let doy = doe - (365*yoe + yoe/4 - yoe/100); // [0,365]
    let mp = (5*doy + 2)/153; // [0,11]
    let d = (doy - (153*mp+2)/5 + 1) as u32; // [1,31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1,12]
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn fmt_frac(nanos: u32) -> String {
    if nanos == 0 { return String::new(); }
    if nanos % 1_000_000 == 0 {
        format!(".{:03}", nanos / 1_000_000)
    } else if nanos % 1000 == 0 {
        format!(".{:06}", nanos / 1000)
    } else {
        format!(".{:09}", nanos)
    }
}

pub fn fmt_date(days: i32) -> String {
    let (y, m, d) = civil_from_days(days as i64);
    if (0..=9999).contains(&y) { format!("{:04}-{:02}-{:02}", y, m, d) } else { format!("{}-{:02}-{:02}", y, m, d) }
}
pub fn fmt_datetime(secs: i64, nanos: u32) -> String {
    let days = secs.div_euclid(86400);
    let sod = secs.rem_euclid(86400);
    let (y, mo, d) = civil_from_days(days);
    let (h, mi, s) = (sod / 3600, (sod % 3600) / 60, sod % 60);
    if (0..=9999).contains(&y) {
        format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}{}", y, mo, d, h, mi, s, fmt_frac(nanos))
    } else {
        format!("{}-{:02}-{:02} {:02}:{:02}:{:02}{}", y, mo, d, h, mi, s, fmt_frac(nanos))
    }
}
pub fn fmt_time(secs: i64, nanos: u32) -> String {
    let sod = secs.rem_euclid(86400);
    let (h, mi, s) = (sod / 3600, (sod % 3600) / 60, sod % 60);
    format!("{:02}:{:02}:{:02}{}", h, mi, s, fmt_frac(nanos))
}

pub fn fmt_decimal(v: i128, scale: i32) -> String {
    if scale <= 0 {
        let mut s = v.to_string();
        for _ in 0..(-scale) { s.push('0'); }
        return s;
    }
    let scale = scale as usize;
    let neg = v < 0;
    let digits = v.unsigned_abs().to_string();
    let padded = if digits.len() <= scale {
        format!("{:0>width$}", digits, width = scale + 1)
    } else { digits };
    let split = padded.len() - scale;
    let out = format!("{}.{}", &padded[..split], &padded[split..]);
    if neg { format!("-{}", out) } else { out }
}

/// Format a datum. `top` = top-level cell (NULL uppercase), else nested.
pub fn format_datum(v: &Datum, top: bool) -> String {
    match v {
        Datum::Unfilled | Datum::Null => if top { "NULL".into() } else { "null".into() },
        Datum::Bool(b) => b.to_string(),
        Datum::I64(x) => x.to_string(),
        Datum::U64(x) => x.to_string(),
        Datum::F32(x) => format!("{:?}", x),
        Datum::F64(x) => format!("{:?}", x),
        Datum::Str(s) => format!("\"{}\"", s),
        Datum::Bin(b) => escape_binary(b),
        Datum::Date(d) => fmt_date(*d),
        Datum::Time(s, n) => fmt_time(*s, *n),
        Datum::Datetime(s, n) => fmt_datetime(*s, *n),
        Datum::Decimal(vv, s) => fmt_decimal(*vv, *s),
        Datum::List(items) => fmt_list(items),
        Datum::Struct(fields) => {
            let inner: Vec<String> = fields.iter().map(|f| format_datum(f, false)).collect();
            format!("{{{}}}", inner.join(","))
        }
    }
}

fn fmt_list(items: &[Datum]) -> String {
    // Polars list display: elide middle when more than 3 elements:
    // [a, b, … z]
    if items.len() > 3 {
        let first: Vec<String> = items[..2].iter().map(|f| format_datum(f, false)).collect();
        let last = format_datum(items.last().unwrap(), false);
        format!("[{}, … {}]", first.join(", "), last)
    } else {
        let inner: Vec<String> = items.iter().map(|f| format_datum(f, false)).collect();
        format!("[{}]", inner.join(", "))
    }
}

/// Truncate to max chars with ellipsis as the final char (visualize cells).
pub fn truncate_str(s: &str, max: usize) -> String {
    if s.chars().count() <= max { s.to_string() } else {
        let mut t: String = s.chars().take(max - 1).collect();
        t.push('…');
        t
    }
}
RS
"}

