pub fn hex_upper(b: &[u8]) -> String {
    b.iter().map(|x| format!("{:02X}", x)).collect()
}

/// Schema-tab Min/Max formatting from raw statistic bytes.
pub fn schema_stat(bytes: Option<&[u8]>, physical: i32) -> String {
    let Some(b) = bytes else { return "NULL".into() };
    if b.is_empty() { return "NULL".into(); }
    match physical {
        1 if b.len() == 4 => i32::from_le_bytes(b.try_into().unwrap()).to_string(),
        2 if b.len() == 8 => i64::from_le_bytes(b.try_into().unwrap()).to_string(),
        4 if b.len() == 4 => format!("{:.4}", f32::from_le_bytes(b.try_into().unwrap())),
        5 if b.len() == 8 => format!("{:.4}", f64::from_le_bytes(b.try_into().unwrap())),
        6 | 7 => match String::from_utf8(b.to_vec()) { Ok(s) => s, Err(_) => hex_upper(b) },
        0 => hex_upper(b),
        _ => "NULL".into(),
    }
}

/// Row-group detail Statistics Min/Max formatting.
pub fn rg_stat(bytes: Option<&[u8]>, physical: i32) -> String {
    let Some(b) = bytes else { return "N/A".into() };
    if b.is_empty() { return "N/A".into(); }
    match physical {
        0 => if b[0] == 0 { "false".into() } else { "true".into() },
        1 if b.len() == 4 => i32::from_le_bytes(b.try_into().unwrap()).to_string(),
        2 if b.len() == 8 => i64::from_le_bytes(b.try_into().unwrap()).to_string(),
        4 if b.len() == 4 => format!("{}", f32::from_le_bytes(b.try_into().unwrap())),
        5 if b.len() == 8 => format!("{}", f64::from_le_bytes(b.try_into().unwrap())),
        6 | 7 => match String::from_utf8(b.to_vec()) { Ok(s) => s, Err(_) => "N/A".into() },
        _ => "N/A".into(),
    }
}
