    pub table_state: TableState,
    pub selected_rg: usize,
    pub viewport_rows: usize,
    pub should_quit: bool,
    pub chart1_comp: Vec<(f64, f64)>,
    pub chart1_uncomp: Vec<(f64, f64)>,
    pub chart2_ratio: Vec<(f64, f64)>,
}

impl App {
    pub fn new(path: String, meta: FileMeta, file: Vec<u8>, table: Table) -> Self {
        let flat = flatten_schema(&meta.root);
        let leaf_order: Vec<usize> = flat.iter().enumerate().filter(|(_, n)| n.is_leaf).map(|(i, _)| i).collect();
        // Visualize strings
        let mut rows_str: Vec<Vec<String>> = Vec::with_capacity(table.height);
        let mut max_lens: Vec<usize> = table.headers.iter().map(|h| h.chars().count()).collect();
        for r in 0..table.height {
            let mut row = Vec::with_capacity(table.headers.len());
            for c in 0..table.headers.len() {
                let s = format_datum(&table.columns[c][r], true);
                if s.chars().count() > max_lens[c] { max_lens[c] = s.chars().count(); }
                row.push(truncate_str(&s, 25));
            }
            rows_str.push(row);
        }
        let headers: Vec<String> = table.headers.iter().map(|h| truncate_str(h, 25)).collect();
        let col_widths: Vec<usize> = max_lens.iter().map(|&m| m.clamp(8, 25) + 2).collect();
        // charts
        let mut c1c = Vec::new(); let mut c1u = Vec::new(); let mut c2 = Vec::new();
        for (i, rg) in meta.row_groups.iter().enumerate() {
            let x = i as f64;
            let comp = rg.compressed() as f64;
            let uncomp = rg.uncompressed() as f64;
            c1c.push((x, comp));
            c1u.push((x, uncomp));
            let ratio = if comp != 0.0 { uncomp / comp } else { 0.0 };
            c2.push((x, ratio));
        }
        Self {
            path, meta, file, headers, rows_str, col_widths, height: table.height,
            flat, leaf_order,
            tab: 0, selected_row: 0, row_scroll: 0, col_offset: 0, schema_col_offset: 0,
            selected_schema: None, list_state: ListState::default(), table_state: TableState::default(),
            selected_rg: 0, viewport_rows: 0, should_quit: false,
            chart1_comp: c1c, chart1_uncomp: c1u, chart2_ratio: c2,
        }
    }

    pub fn on_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Char('q') | KeyCode::Char('Q') => { self.should_quit = true; return; }
            KeyCode::Tab => { self.tab = (self.tab + 1) % 4; return; }
            KeyCode::BackTab => { self.tab = (self.tab + 3) % 4; return; }
            _ => {}
        }
        match self.tab {
            0 => self.on_key_visualize(key),
            2 => self.on_key_schema(key, false),
            3 => self.on_key_rowgroups(key),
            _ => {}
        }
    }

    fn page_step(&self) -> usize {
        self.viewport_rows.saturating_sub(1).max(1)
    }
    fn ensure_row_visible(&mut self) {
        let page = self.page_step();
        if self.selected_row < self.row_scroll { self.row_scroll = self.selected_row; }
        if self.selected_row >= self.row_scroll + page {
            self.row_scroll = self.selected_row - page + 1;
        }
    }
    fn on_key_visualize(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Down => {
                if self.selected_row + 1 < self.height { self.selected_row += 1; }
                self.ensure_row_visible();
            }
            KeyCode::Up => {
                self.selected_row = self.selected_row.saturating_sub(1);
                self.ensure_row_visible();
            }
            KeyCode::Char('d') | KeyCode::Char('D') => {
                if self.height > 0 {
                    self.selected_row = (self.selected_row + self.page_step()).min(self.height - 1);
                    self.ensure_row_visible();
                }
            }
            KeyCode::Char('u') | KeyCode::Char('U') => {
                self.selected_row = self.selected_row.saturating_sub(self.page_step());
                self.ensure_row_visible();
            }
            KeyCode::Right => {
                if self.col_offset + 1 < self.headers.len() { self.col_offset += 1; }
            }
            KeyCode::Left => { self.col_offset = self.col_offset.saturating_sub(1); }
            _ => {}
        }
    }

    fn schema_down(&mut self) {
        let next = match self.selected_schema {
            None => self.leaf_order.first().copied(),
            Some(cur) => self.leaf_order.iter().find(|&&i| i > cur).copied().or(Some(cur)),
        };
        self.set_selected_schema(next);
    }
    fn schema_up(&mut self) {
        let next = match self.selected_schema {
            None => None,
            Some(cur) => self.leaf_order.iter().rev().find(|&&i| i < cur).copied(),
        };
        self.set_selected_schema(next);
    }
    fn set_selected_schema(&mut self, sel: Option<usize>) {
        self.selected_schema = sel;
        self.list_state.select(sel);
        self.table_state.select(sel.map(|i| i - 1));
    }
    fn on_key_schema(&mut self, key: KeyEvent, from_rg: bool) {
        match key.code {
            KeyCode::Down => self.schema_down(),
            KeyCode::Up => self.schema_up(),
            KeyCode::Right if !from_rg => {
                if self.schema_col_offset + 1 < 10 { self.schema_col_offset += 1; }
            }
            KeyCode::Left if !from_rg => { self.schema_col_offset = self.schema_col_offset.saturating_sub(1); }
            _ => {}
        }
    }
    fn on_key_rowgroups(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Down => self.schema_down(),
            KeyCode::Up => self.schema_up(),
            KeyCode::Right => {
                if self.selected_rg + 1 < self.meta.row_groups.len() { self.selected_rg += 1; }
            }
            KeyCode::Left => { self.selected_rg = self.selected_rg.saturating_sub(1); }
            _ => {}
        }
    }

    pub fn render(&mut self, frame: &mut Frame) {
        let area = frame.area();
        let chunks = Layout::vertical([Constraint::Length(3), Constraint::Min(0), Constraint::Length(1)]).split(area);
        self.render_header(frame, chunks[0]);
        match self.tab {
            0 => self.render_visualize(frame, chunks[1]),
            1 => self.render_metadata(frame, chunks[1]),
            2 => self.render_schema(frame, chunks[1]),
            _ => self.render_rowgroups(frame, chunks[1]),
        }
        self.render_footer(frame, chunks[2]);
    }

    fn render_header(&self, frame: &mut Frame, area: Rect) {
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(Style::default().fg(Color::LightYellow));
        let inner = block.inner(area);
        frame.render_widget(block, area);
        let path_len = self.path.chars().count() as u16;
        let cols = Layout::horizontal([Constraint::Min(0), Constraint::Length(path_len)]).split(inner);
        let tabs = Tabs::new(vec!["Visualize", "Metadata", "Schema", "Row Groups"])
            .divider(" ")
            .highlight_style(Style::default().add_modifier(Modifier::REVERSED))
            .select(self.tab);
        frame.render_widget(tabs, cols[0]);
        frame.render_widget(Paragraph::new(self.path.clone()).style(Style::default().fg(Color::Green)), cols[1]);
    }

    fn render_footer(&self, frame: &mut Frame, area: Rect) {
        let cols = Layout::horizontal([Constraint::Length(7), Constraint::Min(0)]).split(area);
        frame.render_widget(Paragraph::new(Line::from(Span::styled("parqeye", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)))), cols[0]);
        frame.render_widget(Paragraph::new(self.help_line()).alignment(Alignment::Right), cols[1]);
    }

    fn key_pair<'a>(&self, a: &'a str, b: &'a str, desc: &'a str) -> Vec<Span<'a>> {
        vec![
            Span::styled(a, Style::default().fg(Color::Green)),
            Span::styled("/", Style::default().fg(Color::White)),
            Span::styled(b, Style::default().fg(Color::Blue)),
            Span::raw(desc),
        ]
    }
    fn help_line<'a>(&self) -> Line<'a> {
        let mut spans: Vec<Span> = Vec::new();
        match self.tab {
            0 => {
                spans.extend(self.key_pair("↑", "↓", " : Row"));
                spans.push(Span::styled(" | ", Style::default().fg(Color::White)));
                spans.extend(self.key_pair("→", "←", " : Column"));
                spans.push(Span::styled(" | ", Style::default().fg(Color::White)));
                spans.extend(self.key_pair("u", "d", " : Page - "));
            }
            2 => {
                spans.extend(self.key_pair("←", "→", " : Scroll, "));
                spans.extend(self.key_pair("↑", "↓", " : Schema - "));
            }
            3 => {
                spans.extend(self.key_pair("→", "←", " : Iterate Row Groups, "));
                spans.extend(self.key_pair("↑", "↓", " : Schema - "));
            }
            _ => {}
        }
        spans.push(Span::styled("[Tab]", Style::default().fg(Color::Green)));
        spans.push(Span::raw(" Next Tab, "));
        spans.push(Span::styled("[Q]", Style::default().fg(Color::Blue)));
        spans.push(Span::raw("uit"));
        Line::from(spans)
    }

    fn render_visualize(&mut self, frame: &mut Frame, area: Rect) {
        let visible_rows = (area.height as usize).saturating_sub(2);
        self.viewport_rows = visible_rows;
        let ncols = self.headers.len();
        let visible_cols = (((area.width as usize).saturating_sub(9)) / 12).max(1);
        let max_start = ncols.saturating_sub(visible_cols);
        let start_col = self.col_offset.min(max_start);
        // header line
        let mut hspans: Vec<Span> = vec![Span::raw(" ".repeat(9))];
        for c in start_col..ncols {
            hspans.push(Span::styled(self.headers[c].clone(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
            let pad = self.col_widths[c].saturating_sub(self.headers[c].chars().count());
            hspans.push(Span::raw(" ".repeat(pad)));
        }
        let mut lines: Vec<Line> = Vec::new();
        lines.push(Line::from(hspans));
        let sep_right = (area.width as usize).saturating_sub(8);
        lines.push(Line::from(Span::styled(format!("{}┬{}", "─".repeat(6), "─".repeat(sep_right)), Style::default().fg(Color::DarkGray))));
        for i in 0..visible_rows {
            let r = self.row_scroll + i;
            if r < self.height {
                let idx_str = (r + 1).to_string();
                let idx_style = if r == self.selected_row {
                    Style::default().fg(Color::DarkGray).add_modifier(Modifier::BOLD | Modifier::UNDERLINED)
                } else { Style::default().fg(Color::DarkGray) };
                let mut content = String::new();
                for c in start_col..ncols {
                    content.push_str(&format!("{:<width$}", self.rows_str[r][c], width = self.col_widths[c]));
                }
                let content_style = if r == self.selected_row {
                    Style::default().fg(Color::White).bg(Color::Rgb(60, 60, 60)).add_modifier(Modifier::BOLD)
                } else { Style::default() };
                lines.push(Line::from(vec![
                    Span::styled(idx_str.clone(), idx_style),
                    Span::raw(" ".repeat(6usize.saturating_sub(idx_str.len()))),
                    Span::styled("│", Style::default().fg(Color::DarkGray)),
                    Span::raw("  "),
                    Span::styled(content, content_style),
                ]));
            } else {
                lines.push(Line::from(vec![
                    Span::raw("      "),
                    Span::styled("│", Style::default().fg(Color::DarkGray)),
                ]));
            }
        }
        frame.render_widget(Paragraph::new(lines), area);
    }

    fn metadata_lines(&self) -> Vec<(String, String)> {
        let m = &self.meta;
        let rows: i64 = m.row_groups.iter().map(|r| r.num_rows).sum();
        let raw: i64 = m.row_groups.iter().flat_map(|r| &r.columns).map(|c| c.total_uncompressed_size).sum();
        let comp: i64 = m.row_groups.iter().flat_map(|r| &r.columns).map(|c| c.total_compressed_size).sum();
        let ratio = if comp != 0 { raw as f64 / comp as f64 } else { 0.0 };
        // codecs
        let mut codec_counts: Vec<(i32, usize)> = Vec::new();
        for rg in &m.row_groups {
            for c in &rg.columns {
                if let Some(e) = codec_counts.iter_mut().find(|e| e.0 == c.codec) { e.1 += 1; } else { codec_counts.push((c.codec, 1)); }
            }
        }
        let codecs = codec_counts.iter().map(|(c, n)| format!("{}({})", codec_debug(*c), n)).collect::<Vec<_>>().join(", ");
        let mut encs = std::collections::BTreeSet::new();
        for rg in &m.row_groups { for c in &rg.columns { for e in &c.encodings { encs.insert(encoding_name(*e)); } } }
        let enc_str = encs.into_iter().collect::<Vec<_>>().join(", ");
        let avg = if rows > 0 { raw / rows } else { 0 };
        vec![
            ("Format version".into(), m.version.to_string()),
            ("Created by".into(), m.created_by.clone().unwrap_or_else(|| "—".into())),
            ("Rows".into(), format_number(rows)),
            ("Columns".into(), leaf_count(&m.root).to_string()),
            ("Row groups".into(), m.row_groups.len().to_string()),
            ("Size (raw)".into(), fmt_bytes_kib(raw)),
            ("Size (compressed)".into(), fmt_bytes_kib(comp)),
            ("Compression ratio".into(), format!("{:.2}x", ratio)),
            ("Codecs (cols)".into(), codecs),
            ("Encodings".into(), enc_str),
            ("Avg row size".into(), format!("{} B", avg)),
        ]
    }

    fn render_metadata(&self, frame: &mut Frame, area: Rect) {
        let pairs = self.metadata_lines();
        let lines: Vec<Line> = pairs.iter().map(|(l, v)| {
            Line::from(vec![
                Span::styled(format!("{:>18}", l), Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD)),
                Span::raw(" "),
                Span::raw(v.clone()),
            ])
        }).collect();
        let max_len = pairs.iter().map(|(_, v)| 19 + v.chars().count()).max().unwrap_or(0);
        let desired_w = (max_len + 4) as u16;
        let desired_h = (pairs.len() + 2) as u16;
        let v = Layout::vertical([Constraint::Fill(1), Constraint::Length(desired_h), Constraint::Fill(1)]).split(area);
        let h = Layout::horizontal([Constraint::Fill(1), Constraint::Length(desired_w), Constraint::Fill(1)]).split(v[1]);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title_top(Line::from(Span::styled("File Metadata", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))).centered());
        frame.render_widget(Paragraph::new(lines).block(block), h[1]);
    }

    fn schema_tree_width(&self, rg: bool, scrollable: bool) -> u16 {
        let max_byte = self.flat.iter().map(|n| n.tree_line.len()).max().unwrap_or(0) as u16;
        if rg && !scrollable {
            max_byte.max(24)
        } else {
            (max_byte + 1).max(25)
        }
    }

    fn render_schema_tree(&mut self, frame: &mut Frame, area: Rect, rg: bool) -> Rect {
        // Returns the remaining area to the right.
        let inner_h = (area.height as usize).saturating_sub(2);
        let scrollable = self.flat.len() > inner_h;
        let desired = self.schema_tree_width(rg, scrollable);
        let scroll_w: u16 = if scrollable { 1 } else { 0 };
        let left_w = desired.min(area.width.saturating_sub(scroll_w));
        let left = Rect::new(area.x, area.y, left_w, area.height);
        let scroll_rect = Rect::new(area.x + left_w, area.y, scroll_w, area.height);
        let right_x = area.x + left_w + scroll_w;
        let right = Rect::new(right_x, area.y, area.width.saturating_sub(left_w + scroll_w), area.height);
        // Build block with titles
        let mut bottom_spans = vec![
            Span::styled("Leaf", Style::default().fg(Color::White)),
            Span::raw(", "),
            Span::styled("Group", Style::default().fg(Color::Green)),
        ];
        if self.selected_schema.is_some() {
            bottom_spans.push(Span::raw(", "));
            bottom_spans.push(Span::styled("Selected", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
        }
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title_top(Line::from(Span::styled("Schema Tree", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))).centered())
            .title_bottom(Line::from(bottom_spans).centered());
        let items: Vec<ListItem> = self.flat.iter().enumerate().map(|(i, n)| {
            let style = if Some(i) == self.selected_schema {
                Style::default().fg(Color::Black).bg(Color::Yellow)
            } else if i == 0 {
                Style::default().fg(Color::LightYellow)
            } else if n.is_leaf {
                Style::default().fg(Color::White)
            } else {
                Style::default().fg(Color::Green)
            };
            ListItem::new(Line::from(Span::styled(n.tree_line.clone(), style)))
        }).collect();
        let list = List::new(items)
            .block(block)
            .highlight_style(Style::default().fg(Color::Black).bg(Color::Yellow))
            .highlight_symbol("");
        // clone state to render (we need &mut state while self borrowed for items - items owned, fine)
        frame.render_stateful_widget(list, left, &mut self.list_state);
        if scrollable && scroll_w > 0 {
            let offset = self.list_state.offset();
            let mut sstate = ScrollbarState::new(self.flat.len())
                .position(offset)
                .viewport_content_length(inner_h);
            let scrollbar = Scrollbar::new(ScrollbarOrientation::VerticalRight)
                .begin_symbol(None)
                .end_symbol(None)
                .track_symbol(Some("│"))
                .thumb_symbol("█");
            frame.render_stateful_widget(scrollbar, scroll_rect, &mut sstate);
        }
        right
    }

    fn leaf_stats(&self, leaf_idx: usize) -> (i64, i64, f64, String, i32, String, String, i64) {
        let mut comp: i64 = 0; let mut uncomp: i64 = 0;
        let mut encset: HashSet<String> = HashSet::new();
        let mut codec = 0i32;
        let mut nulls: i64 = 0;
        let mut min_s = "NULL".to_string(); let mut max_s = "NULL".to_string();
        let mut first_stats = true;
        // physical type from leaf node
        let phys = self.flat.iter().filter(|n| n.is_leaf).nth(leaf_idx).map(|n| n.physical.unwrap_or(6)).unwrap_or(6);
        for (ri, rg) in self.meta.row_groups.iter().enumerate() {
            if let Some(c) = rg.columns.get(leaf_idx) {
                comp += c.total_compressed_size;
                uncomp += c.total_uncompressed_size;
                if ri == 0 { codec = c.codec; }
                for e in &c.encodings { encset.insert(encoding_name(*e)); }
                if let Some(st) = &c.statistics {
                    nulls += st.null_count.unwrap_or(0);
                    if first_stats {
                        min_s = schema_stat(st.min_bytes(), phys);
                        max_s = schema_stat(st.max_bytes(), phys);
                        first_stats = false;
                    }
                }
            }
        }
        let ratio = if comp != 0 { uncomp as f64 / comp as f64 } else { 0.0 };
        let enc_str = encset.into_iter().collect::<Vec<_>>().join(", ");
        (comp, uncomp, ratio, enc_str, codec, min_s, max_s, nulls)
    }

    fn render_schema(&mut self, frame: &mut Frame, area: Rect) {
        // Need right area: render tree first (it computes layout), but tree needs &mut.
        // We render tree and get right rect, then table.
        let right = self.render_schema_tree(frame, area, false);
        let headers = ["Repetition", "Physical", "Compressed", "Uncompressed", "Ratio", "Encodings", "Compression", "Min", "Max", "Nulls"];
        // build all rows strings
        let mut all_rows: Vec<Vec<String>> = Vec::new();
        let mut is_group_row: Vec<bool> = Vec::new();
        for n in self.flat.iter().skip(1) {
            let rep = match n.repetition { Some(0) => "REQUIRED", Some(1) => "OPTIONAL", Some(2) => "REPEATED", _ => "REQUIRED" }.to_string();
            if n.is_leaf {
                let li = n.leaf_index.unwrap_or(0);
                let (comp, uncomp, ratio, enc, codec, mn, mx, nulls) = self.leaf_stats(li);
                all_rows.push(vec![rep, physical_name(n.physical.unwrap_or(6)).into(), fmt_bytes_kb(comp), fmt_bytes_kb(uncomp), format!("{:.2}x", ratio), enc, codec_debug(codec), mn, mx, nulls.to_string()]);
                is_group_row.push(false);
            } else {
                let mut r = vec![rep, "group".into()];
                r.resize(10, String::new());
                all_rows.push(r);
                is_group_row.push(true);
            }
        }
        // widths per column (max len + 1)
        let mut widths: Vec<u16> = headers.iter().map(|h| h.len() as u16).collect();
        for r in &all_rows {
            for (i, c) in r.iter().enumerate() { widths[i] = widths[i].max(c.len() as u16); }
        }
        let visible_cols = (((right.width as usize).saturating_sub(4)) / 12).max(1);
        let max_start = headers.len().saturating_sub(visible_cols);
        let start = self.schema_col_offset.min(max_start);
        let header_row = Row::new(headers[start..].iter().map(|h| Cell::from(*h).style(Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))).collect::<Vec<_>>());
        let rows: Vec<Row> = all_rows.iter().enumerate().map(|(ri, r)| {
            let cells: Vec<Cell> = r[start..].iter().enumerate().map(|(ci, c)| {
                let actual_col = start + ci;
                if is_group_row[ri] && actual_col < 2 {
                    Cell::from(c.clone()).style(Style::default().fg(Color::Green))
                } else { Cell::from(c.clone()) }
            }).collect();
            Row::new(cells)
        }).collect();
        let constraints: Vec<Constraint> = widths[start..].iter().map(|w| Constraint::Length(w + 1)).collect();
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title_top(Line::from(Span::styled("Column Statistics", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD))).centered());
        let table = RTable::new(rows, constraints)
            .header(header_row)
            .block(block)
            .row_highlight_style(Style::default().fg(Color::Black).bg(Color::Yellow))
            .highlight_symbol("");
        frame.render_stateful_widget(table, right, &mut self.table_state);
    }

    fn render_rowgroups(&mut self, frame: &mut Frame, area: Rect) {
        let right = self.render_schema_tree(frame, area, true);
        if self.meta.row_groups.is_empty() { return; }
        let n_rg = self.meta.row_groups.len();
        let sel = self.selected_rg.min(n_rg - 1);
        if self.selected_schema.is_some() {
            self.render_rg_detail(frame, right, sel);
        } else {
            self.render_rg_overview(frame, right, sel);
        }
    }

    fn gauge_block(&self, frame: &mut Frame, area: Rect, sel: usize) {
        let n = self.meta.row_groups.len();
        let title = format!(" Row Group: {} / {} ", sel + 1, n);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_style(Style::default().fg(Color::Gray))
            .title_top(Line::from(Span::styled(title, Style::default().add_modifier(Modifier::BOLD))).left_aligned());
        let ratio = if n > 0 { (sel + 1) as f64 / n as f64 } else { 0.0 };
        let gauge = Gauge::default()
            .block(block)
            .gauge_style(Style::default().fg(Color::Blue))
            .label("")
            .ratio(ratio);
        frame.render_widget(gauge, area);
    }

    fn render_rg_overview(&mut self, frame: &mut Frame, area: Rect, sel: usize) {
        let v = Layout::vertical([Constraint::Length(3), Constraint::Length(3), Constraint::Min(0)]).split(area);
        self.gauge_block(frame, v[0], sel);
        // cards
        let rg = &self.meta.row_groups[sel];
        let total_rows: i64 = self.meta.row_groups.iter().map(|r| r.num_rows).sum();
        let total_comp: i64 = self.meta.row_groups.iter().map(|r| r.compressed()).sum();
        let total_uncomp: i64 = self.meta.row_groups.iter().map(|r| r.uncompressed()).sum();
        let sel_ratio = if rg.compressed() != 0 { rg.uncompressed() as f64 / rg.compressed() as f64 } else { 0.0 };
        let tot_ratio = if total_comp != 0 { total_uncomp as f64 / total_comp as f64 } else { 0.0 };
        let cards: Vec<(&str, String, String)> = vec![
            ("Rows", format_number(rg.num_rows), format_number(total_rows)),
            ("Compressed", fmt_bytes_kib(rg.compressed()), fmt_bytes_kib(total_comp)),
            ("Uncompressed", fmt_bytes_kib(rg.uncompressed()), fmt_bytes_kib(total_uncomp)),
            ("Ratio", format!("{:.2}", sel_ratio), format!("{:.2}", tot_ratio)),
        ];
        let card_area = Layout::horizontal([Constraint::Percentage(25), Constraint::Percentage(25), Constraint::Percentage(25), Constraint::Percentage(25)]).split(v[1]);
        for (i, (title, value, total)) in cards.iter().enumerate() {
            let bottom = Line::from(vec![
                Span::styled(value.clone(), Style::default().fg(Color::LightCyan)),
                Span::styled(" / ", Style::default().fg(Color::White)),
                Span::styled(total.clone(), Style::default().fg(Color::LightMagenta)),
            ]).style(Style::default().add_modifier(Modifier::BOLD)).centered();
            let block = Block::default()
                .borders(Borders::ALL)
                .border_style(Style::default().fg(Color::Blue))
                .title_top(Line::from(Span::styled(*title, Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD))).left_aligned())
                .title_bottom(bottom);
            let p = Paragraph::new(Line::from(Span::styled(value.clone(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))))
                .block(block)
                .alignment(Alignment::Center);
            frame.render_widget(p, card_area[i]);
        }
        // charts in left half
        let charts_area = v[2];
        let chart_w = (charts_area.width + 1) / 2;
        let chart_col = Rect::new(charts_area.x, charts_area.y, chart_w, charts_area.height);
        let cv = Layout::vertical([Constraint::Percentage(50), Constraint::Percentage(50)]).split(chart_col);
        self.render_chart1(frame, cv[0]);
        self.render_chart2(frame, cv[1]);
    }

    fn x_labels(&self) -> Vec<Span<'static>> {
        (0..self.meta.row_groups.len()).map(|i| Span::raw(format!("{}", i + 1))).collect()
    }
    fn x_bounds(&self) -> [f64; 2] {
        let n = self.meta.row_groups.len();
        [0.0, (n.saturating_sub(1)) as f64]
    }

    fn render_chart1(&self, frame: &mut Frame, area: Rect) {
        let max_size = self.chart1_comp.iter().chain(self.chart1_uncomp.iter()).map(|p| p.1).fold(0.0f64, f64::max);
        let y_max = max_size * 1.5;
        let labels: Vec<Span> = (0..4).map(|i| {
            let val = if y_max > 0.0 { y_max * i as f64 / 4.0 } else { i as f64 };
            Span::raw(fmt_axis(val))
        }).collect();
        let datasets = vec![
            Dataset::default()
                .name("Compressed")
                .marker(symbols::Marker::Dot)
                .graph_type(GraphType::Scatter)
                .style(Style::default().fg(Color::Blue))
                .data(&self.chart1_comp),
            Dataset::default()
                .name("Uncompressed")
                .marker(symbols::Marker::Dot)
                .graph_type(GraphType::Scatter)
                .style(Style::default().fg(Color::Red))
                .data(&self.chart1_uncomp),
        ];
        let title_line = Line::from(vec![
            Span::styled("Compressed", Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD)),
            Span::raw(" vs "),
            Span::styled("Uncompressed", Style::default().fg(Color::LightRed).add_modifier(Modifier::BOLD)),
            Span::raw(" (B)"),
        ]).centered();
        let block = Block::default()
            .title_top(title_line)
            .title_bottom(Line::from(Span::styled("Row Group", Style::default().fg(Color::DarkGray))).left_aligned());
        let chart = Chart::new(datasets)
            .block(block)
            .x_axis(Axis::default()
                .style(Style::default().fg(Color::White))
                .bounds(self.x_bounds())
                .labels(self.x_labels()))
            .y_axis(Axis::default()
                .style(Style::default().fg(Color::White))
                .bounds([0.0, if y_max > 0.0 { y_max } else { 1.0 }])
                .labels(labels)
                .labels_alignment(Alignment::Left))
            .legend_position(Some(LegendPosition::TopRight));
        frame.render_widget(chart, area);
    }

    fn render_chart2(&self, frame: &mut Frame, area: Rect) {
        let max_ratio = self.chart2_ratio.iter().map(|p| p.1).fold(0.0f64, f64::max);
        let y_min = 1.0f64;
        let y_max = max_ratio * 1.1;
        let labels: Vec<Span> = (0..4).map(|i| {
            let val = y_min + (y_max - y_min) * i as f64 / 4.0;
            Span::raw(format!("{:.1}x", val))
        }).collect();
        let datasets = vec![
            Dataset::default()
                .marker(symbols::Marker::Dot)
                .graph_type(GraphType::Scatter)
                .style(Style::default().fg(Color::Yellow))
                .data(&self.chart2_ratio),
        ];
        let block = Block::default()
            .title_top(Line::from(Span::styled("Compression Ratio", Style::default().fg(Color::Yellow))).left_aligned())
            .title_bottom(Line::from(Span::styled("Row Group", Style::default().fg(Color::DarkGray))).left_aligned());
        let chart = Chart::new(datasets)
            .block(block)
            .x_axis(Axis::default()
                .style(Style::default().fg(Color::White))
                .bounds(self.x_bounds())
                .labels(self.x_labels()))
            .y_axis(Axis::default()
                .style(Style::default().fg(Color::White))
                .bounds([y_min, y_max])
                .labels(labels)
                .labels_alignment(Alignment::Left));
        frame.render_widget(chart, area);
    }

    fn render_rg_detail(&mut self, frame: &mut Frame, area: Rect, sel: usize) {
        let v = Layout::vertical([Constraint::Length(3), Constraint::Length(1), Constraint::Length(3), Constraint::Min(0)]).split(area);
        self.gauge_block(frame, v[0], sel);
        let flat_idx = self.selected_schema.unwrap_or(0);
        let leaf_idx = self.flat[flat_idx].leaf_index.unwrap_or(0);
        let rg = &self.meta.row_groups[sel];
        let Some(chunk) = rg.columns.get(leaf_idx).cloned() else { return };
        let col_path = chunk.path.join(".");
        // separator
        let quoted = format!("\"{}\"", col_path);
        let title_len = 9 + quoted.chars().count() + 1;
        let w = v[1].width as usize;
        let left_dashes = w.saturating_sub(title_len) / 2;
        let right_dashes = w.saturating_sub(title_len + left_dashes);
        let sep = Line::from(vec![
            Span::styled("─".repeat(left_dashes), Style::default().fg(Color::Blue)),
            Span::styled(" Column: ", Style::default().fg(Color::Blue)),
            Span::styled(quoted, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
            Span::styled(format!(" {}", "─".repeat(right_dashes)), Style::default().fg(Color::Blue)),
        ]);
        frame.render_widget(Paragraph::new(sep), v[1]);
        // indicator cards
        let indicators: Vec<(&str, bool)> = vec![
            ("Statistics", chunk.statistics.is_some()),
            ("Dict Page", chunk.dictionary_page_offset.is_some()),
            ("Bloom Filter", chunk.bloom_filter_offset.is_some()),
            ("Page Stats", chunk.has_encoding_stats),
        ];
        let card_area = Layout::horizontal([Constraint::Percentage(25), Constraint::Percentage(25), Constraint::Percentage(25), Constraint::Percentage(25)]).split(v[2]);
        for (i, (title, present)) in indicators.iter().enumerate() {
            let color = if *present { Color::Green } else { Color::Red };
            let symbol = if *present { "✓" } else { "✗" };
            let block = Block::default()
                .borders(Borders::ALL)
                .border_style(Style::default().fg(color))
                .title_top(Line::from(Span::styled(*title, Style::default().add_modifier(Modifier::BOLD))).left_aligned());
            let p = Paragraph::new(Line::from(Span::styled(symbol, Style::default().fg(color).add_modifier(Modifier::BOLD))))
                .block(block)
                .alignment(Alignment::Center);
            frame.render_widget(p, card_area[i]);
        }
        // lower: metadata/stats left, pages right
        let lower = Layout::horizontal([Constraint::Percentage(38), Constraint::Percentage(62)]).split(v[3]);
        let ratio = if chunk.total_compressed_size != 0 { chunk.total_uncompressed_size as f64 / chunk.total_compressed_size as f64 } else { 0.0 };
        let meta_rows: Vec<(String, String)> = vec![
            ("File Offset (B)".into(), format_number(chunk.file_offset)),
            ("Compressed Size".into(), fmt_bytes_kib(chunk.total_compressed_size)),
            ("Uncompressed Size".into(), fmt_bytes_kib(chunk.total_uncompressed_size)),
            ("Compression Ratio".into(), format!("{:.2}x", ratio)),
            ("Compression Type".into(), codec_debug(chunk.codec)),
        ];
        let mut left_chunks = vec![Constraint::Length(7)];
        if chunk.statistics.is_some() { left_chunks.push(Constraint::Length(6)); }
        left_chunks.push(Constraint::Min(0));
        let lv = Layout::vertical(left_chunks).split(lower[0]);
        render_kv_table(frame, lv[0], "Metadata", Color::Blue, &meta_rows, true);
        if let Some(st) = &chunk.statistics {
            let phys = chunk.physical_type;
            let stat_rows: Vec<(String, String)> = vec![
                ("Min".into(), rg_stat(st.min_bytes(), phys)),
                ("Max".into(), rg_stat(st.max_bytes(), phys)),
                ("Null Count".into(), st.null_count.map(|n| n.to_string()).unwrap_or_else(|| "0".into())),
                ("Distinct Count".into(), st.distinct_count.map(|n| n.to_string()).unwrap_or_else(|| "N/A".into())),
            ];
            render_kv_table(frame, lv[1], "Statistics", Color::Magenta, &stat_rows, false);
        }
        // Pages
        let phys = chunk.physical_type;
        let leaf_node = &self.flat[flat_idx];
        let _ = leaf_node;
        let tl = node_at(&self.meta.root, &leaf_node.node_path).type_length.unwrap_or(0);
        let infos = read_column(&self.file, &chunk, phys, tl, 0, 0, true).map(|(_, i)| i).unwrap_or_default();
        let header = Row::new(["#", "Page Type", "Size", "Rows", "Encoding"].iter().map(|h| Cell::from(*h).style(Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))).collect::<Vec<_>>());
        let rows: Vec<Row> = infos.iter().enumerate().map(|(i, p)| {
            Row::new(vec![
                Cell::from((i + 1).to_string()).style(Style::default().fg(Color::White)),
                Cell::from(page_type_name(p.page_type)).style(Style::default().fg(Color::Cyan)),
                Cell::from(fmt_bytes_kib(p.uncompressed_size)).style(Style::default().fg(Color::White)),
                Cell::from(format_number(p.num_values)).style(Style::default().fg(Color::White)),
                Cell::from(encoding_label(p.encoding)).style(Style::default().fg(Color::Green)),
            ])
        }).collect();
        let block = Block::default()
            .borders(Borders::ALL)
            .border_style(Style::default().fg(Color::DarkGray))
            .title_top(Line::from("Pages").left_aligned());
        let table = RTable::new(rows, [Constraint::Length(3), Constraint::Min(20), Constraint::Min(21), Constraint::Min(14), Constraint::Min(20)])
            .header(header)
            .block(block);
        frame.render_widget(table, lower[1]);
    }
}

fn render_kv_table(frame: &mut Frame, area: Rect, title: &str, border: Color, rows_kv: &[(String, String)], cyan_labels: bool) {
    let rows: Vec<Row> = rows_kv.iter().map(|(k, v)| {
        let label_style = if cyan_labels {
            Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)
        } else {
            Style::default().add_modifier(Modifier::BOLD)
        };
        Row::new(vec![
            Cell::from(k.clone()).style(label_style),
            Cell::from(v.clone()).style(Style::default().fg(Color::White)),
        ])
    }).collect();
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(border))
        .title_top(Line::from(title.to_string()).left_aligned());
    let table = RTable::new(rows, [Constraint::Length(18), Constraint::Min(0)]).block(block);
    frame.render_widget(table, area);
}

fn page_type_name(t: i32) -> String {
    match t { 0 => "Data Page".into(), 1 => "Index Page".into(), 2 => "Dictionary Page".into(), 3 => "Data Page V2".into(), _ => "Unknown".into() }
}
fn encoding_label(e: i32) -> String {
    match e {
        0 => "Plain".into(), 2 => "Plain Dictionary".into(), 3 => "RLE".into(), 8 => "RLE Dictionary".into(),
        4 => "Bit Packed".into(), 5 => "Delta Binary Packed".into(), 6 => "Delta Length Byte Array".into(),
        7 => "Delta Byte Array".into(), 9 => "Byte Stream Split".into(), 1 => "Group Var Int".into(),
        _ => "Unknown".into(),
    }
}
RS
"}

actions.command:
cat > src/ui.rs <<'RS'
use crate::data::{Datum, Table};
use crate::fmt::*;
use crate::meta::*;
use crate::page::read_column;
use ratatui::{
    crossterm::event::{KeyCode, KeyEvent},
    layout::{Alignment, Constraint, Layout, Rect},
    style::{Color, Modifier, Style},
    symbols,
    text::{Line, Span},
    widgets::{
        Axis, Block, BorderType, Borders, Cell, Chart, Dataset, Gauge, GraphType,
        LegendPosition, List, ListItem, ListState, Paragraph, Row, Scrollbar,
        ScrollbarOrientation, ScrollbarState, Table as RTable, TableState, Tabs,
    },
    Frame,
};
use std::collections::HashSet;

pub struct App {
    pub path: String,
    pub meta: FileMeta,
    pub file: Vec<u8>,
    pub headers: Vec<String>,
    pub rows_str: Vec<Vec<String>>, // [row][col] truncated strings
    pub col_widths: Vec<usize>,
    pub height: usize,
    pub flat: Vec<FlatNode>,
    pub leaf_order: Vec<usize>, // flat indices of leaves in order
    pub tab: usize,
    pub selected_row: usize,
    pub row_scroll: usize,
    pub col_offset: usize,
    pub schema_col_offset: usize,
    pub selected_schema: Option<usize>, // flat index
    pub list_state: ListState,
    pub table_state: TableState,
    pub selected_rg: usize,
    pub viewport_rows: usize,
    pub should_quit: bool,
    pub chart1_comp: Vec<(f64, f64)>,
    pub chart1_uncomp: Vec<(f64, f64)>,
    pub chart2_ratio: Vec<(f64, f64)>,
}

impl App {
    pub fn new(path: String, meta: FileMeta, file: Vec<u8>, table: Table) -> Self {
        let flat = flatten_schema(&meta.root);
        let leaf_order: Vec<usize> = flat.iter().enumerate().filter(|(_, n)| n.is_leaf).map(|(i, _)| i).collect();
        // Visualize strings
        let mut rows_str: Vec<Vec<String>> = Vec::with_capacity(table.height);
        let mut max_lens: Vec<usize> = table.headers.iter().map(|h| h.chars().count()).collect();
        for r in 0..table.height {
            let mut row = Vec::with_capacity(table.headers.len());
            for c in 0..table.headers.len() {
                let s = format_datum(&table.columns[c][r], true);
                if s.chars().count() > max_lens[c] { max_lens[c] = s.chars().count(); }
                row.push(truncate_str(&s, 25));
            }
            rows_str.push(row);
        }
        let headers: Vec<String> = table.headers.iter().map(|h| truncate_str(h, 25)).collect();
        let col_widths: Vec<usize> = max_lens.iter().map(|&m| m.clamp(8, 25) + 2).collect();
        // charts
        let mut c1c = Vec::new(); let mut c1u = Vec::new(); let mut c2 = Vec::new();
        for (i, rg) in meta.row_groups.iter().enumerate() {
            let x = i as f64;
            let comp = rg.compressed() as f64;
            let uncomp = rg.uncompressed() as f64;
            c1c.push((x, comp));
            c1u.push((x, uncomp));
            let ratio = if comp != 0.0 { uncomp / comp } else { 0.0 };
            c2.push((x, ratio));
        }
        Self {
            path, meta, file, headers, rows_str, col_widths, height: table.height,
            flat, leaf_order,
            tab: 0, selected_row: 0, row_scroll: 0, col_offset: 0, schema_col_offset: 0,
            selected_schema: None, list_state: ListState::default(), table_state: TableState::default(),
            selected_rg: 0, viewport_rows: 0, should_quit: false,
            chart1_comp: c1c, chart1_uncomp: c1u, chart2_ratio: c2,
        }
    }

    pub fn on_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Char('q') | KeyCode::Char('Q') => { self.should_quit = true; return; }
            KeyCode::Tab => { self.tab = (self.tab + 1) % 4; return; }
            KeyCode::BackTab => { self.tab = (self.tab + 3) % 4; return; }
            _ => {}
        }
        match self.tab {
            0 => self.on_key_visualize(key),
            2 => self.on_key_schema(key, false),
            3 => self.on_key_rowgroups(key),
            _ => {}
        }
    }

    fn page_step(&self) -> usize {
        self.viewport_rows.saturating_sub(1).max(1)
    }
    fn ensure_row_visible(&mut self) {
        let page = self.page_step();
        if self.selected_row < self.row_scroll { self.row_scroll = self.selected_row; }
        if self.selected_row >= self.row_scroll + page {
            self.row_scroll = self.selected_row - page + 1;
        }
    }
    fn on_key_visualize(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Down => {
                if self.selected_row + 1 < self.height { self.selected_row += 1; }
                self.ensure_row_visible();
            }
            KeyCode::Up => {
                self.selected_row = self.selected_row.saturating_sub(1);
                self.ensure_row_visible();
            }
            KeyCode::Char('d') | KeyCode::Char('D') => {
                if self.height > 0 {
                    self.selected_row = (self.selected_row + self.page_step()).min(self.height - 1);
                    self.ensure_row_visible();
                }
            }
            KeyCode::Char('u') | KeyCode::Char('U') => {
                self.selected_row = self.selected_row.saturating_sub(self.page_step());
                self.ensure_row_visible();
            }
            KeyCode::Right => {
                if self.col_offset + 1 < self.headers.len() { self.col_offset += 1; }
            }
            KeyCode::Left => { self.col_offset = self.col_offset.saturating_sub(1); }
            _ => {}
        }
    }

    fn schema_down(&mut self) {
        let next = match self.selected_schema {
            None => self.leaf_order.first().copied(),
            Some(cur) => self.leaf_order.iter().find(|&&i| i > cur).copied().or(Some(cur)),
        };
        self.set_selected_schema(next);
    }
    fn schema_up(&mut self) {
        let next = match self.selected_schema {
            None => None,
            Some(cur) => self.leaf_order.iter().rev().find(|&&i| i < cur).copied(),
        };
        self.set_selected_schema(next);
    }
    fn set_selected_schema(&mut self, sel: Option<usize>) {
        self.selected_schema = sel;
        self.list_state.select(sel);
        self.table_state.select(sel.map(|i| i - 1));
    }
    fn on_key_schema(&mut self, key: KeyEvent, from_rg: bool) {
        match key.code {
            KeyCode::Down => self.schema_down(),
            KeyCode::Up => self.schema_up(),
            KeyCode::Right if !from_rg => {
                if self.schema_col_offset + 1 < 10 { self.schema_col_offset += 1; }
            }
            KeyCode::Left if !from_rg => { self.schema_col_offset = self.schema_col_offset.saturating_sub(1); }
            _ => {}
        }
    }
    fn on_key_rowgroups(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Down => self.schema_down(),
            KeyCode::Up => self.schema_up(),
            KeyCode::Right => {
                if self.selected_rg + 1 < self.meta.row_groups.len() { self.selected_rg += 1; }
            }
            KeyCode::Left => { self.selected_rg = self.selected_rg.saturating_sub(1); }
            _ => {}
        }
    }

    pub fn render(&mut self, frame: &mut Frame) {
        let area = frame.area();
        let chunks = Layout::vertical([Constraint::Length(3), Constraint::Min(0), Constraint::Length(1)]).split(area);
        self.render_header(frame, chunks[0]);
        match self.tab {
            0 => self.render_visualize(frame, chunks[1]),
            1 => self.render_metadata(frame, chunks[1]),
            2 => self.render_schema(frame, chunks[1]),
            _ => self.render_rowgroups(frame, chunks[1]),
        }
        self.render_footer(frame, chunks[2]);
    }

    fn render_header(&self, frame: &mut Frame, area: Rect) {
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(Style::default().fg(Color::LightYellow));
        let inner = block.inner(area);
        frame.render_widget(block, area);
        let path_len = self.path.chars().count() as u16;
        let cols = Layout::horizontal([Constraint::Min(0), Constraint::Length(path_len)]).split(inner);
        let tabs = Tabs::new(vec!["Visualize", "Metadata", "Schema", "Row Groups"])
            .divider(" ")
            .highlight_style(Style::default().add_modifier(Modifier::REVERSED))
            .select(self.tab);
        frame.render_widget(tabs, cols[0]);
        frame.render_widget(Paragraph::new(self.path.clone()).style(Style::default().fg(Color::Green)), cols[1]);
    }

    fn render_footer(&self, frame: &mut Frame, area: Rect) {
        let cols = Layout::horizontal([Constraint::Length(7), Constraint::Min(0)]).split(area);
        frame.render_widget(Paragraph::new(Line::from(Span::styled("parqeye", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)))), cols[0]);
        frame.render_widget(Paragraph::new(self.help_line()).alignment(Alignment::Right), cols[1]);
    }

    fn key_pair<'a>(&self, a: &'a str, b: &'a str, desc: &'a str) -> Vec<Span<'a>> {
        vec![
            Span::styled(a, Style::default().fg(Color::Green)),
            Span::styled("/", Style::default().fg(Color::White)),
            Span::styled(b, Style::default().fg(Color::Blue)),
            Span::raw(desc),
        ]
    }
    fn help_line<'a>(&self) -> Line<'a> {
        let mut spans: Vec<Span> = Vec::new();
        match self.tab {
            0 => {
                spans.extend(self.key_pair("↑", "↓", " : Row"));
                spans.push(Span::styled(" | ", Style::default().fg(Color::White)));
                spans.extend(self.key_pair("→", "←", " : Column"));
                spans.push(Span::styled(" | ", Style::default().fg(Color::White)));
                spans.extend(self.key_pair("u", "d", " : Page - "));
            }
            2 => {
                spans.extend(self.key_pair("←", "→", " : Scroll, "));
                spans.extend(self.key_pair("↑", "↓", " : Schema - "));
            }
            3 => {
                spans.extend(self.key_pair("→", "←", " : Iterate Row Groups, "));
                spans.extend(self.key_pair("↑", "↓", " : Schema - "));
            }
            _ => {}
        }
        spans.push(Span::styled("[Tab]", Style::default().fg(Color::Green)));
        spans.push(Span::raw(" Next Tab, "));
        spans.push(Span::styled("[Q]", Style::default().fg(Color::Blue)));
        spans.push(Span::raw("uit"));
        Line::from(spans)
    }

    fn render_visualize(&mut self, frame: &mut Frame, area: Rect) {
        let visible_rows = (area.height as usize).saturating_sub(2);
        self.viewport_rows = visible_rows;
        let ncols = self.headers.len();
        let visible_cols = (((area.width as usize).saturating_sub(9)) / 12).max(1);
        let max_start = ncols.saturating_sub(visible_cols);
        let start_col = self.col_offset.min(max_start);
        // header line
        let mut hspans: Vec<Span> = vec![Span::raw(" ".repeat(9))];
        for c in start_col..ncols {
            hspans.push(Span::styled(self.headers[c].clone(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
            let pad = self.col_widths[c].saturating_sub(self.headers[c].chars().count());
            hspans.push(Span::raw(" ".repeat(pad)));
        }
        let mut lines: Vec<Line> = Vec::new();
        lines.push(Line::from(hspans));
        let sep_right = (area.width as usize).saturating_sub(8);
        lines.push(Line::from(Span::styled(format!("{}┬{}", "─".repeat(6), "─".repeat(sep_right)), Style::default().fg(Color::DarkGray))));
        for i in 0..visible_rows {
            let r = self.row_scroll + i;
            if r < self.height {
                let idx_str = (r + 1).to_string();
                let idx_style = if r == self.selected_row {
                    Style::default().fg(Color::DarkGray).add_modifier(Modifier::BOLD | Modifier::UNDERLINED)
                } else { Style::default().fg(Color::DarkGray) };
                let mut content = String::new();
                for c in start_col..ncols {
                    content.push_str(&format!("{:<width$}", self.rows_str[r][c], width = self.col_widths[c]));
                }
                let content_style = if r == self.selected_row {
                    Style::default().fg(Color::White).bg(Color::Rgb(60, 60, 60)).add_modifier(Modifier::BOLD)
                } else { Style::default() };
                lines.push(Line::from(vec![
                    Span::styled(idx_str.clone(), idx_style),
                    Span::raw(" ".repeat(6usize.saturating_sub(idx_str.len()))),
                    Span::styled("│", Style::default().fg(Color::DarkGray)),
                    Span::raw("  "),
                    Span::styled(content, content_style),
                ]));
            } else {
                lines.push(Line::from(vec![
                    Span::raw("      "),
                    Span::styled("│", Style::default().fg(Color::DarkGray)),
                ]));
            }
        }
        frame.render_widget(Paragraph::new(lines), area);
    }

    fn metadata_lines(&self) -> Vec<(String, String)> {
        let m = &self.meta;
        let rows: i64 = m.row_groups.iter().map(|r| r.num_rows).sum();
        let raw: i64 = m.row_groups.iter().flat_map(|r| &r.columns).map(|c| c.total_uncompressed_size).sum();
        let comp: i64 = m.row_groups.iter().flat_map(|r| &r.columns).map(|c| c.total_compressed_size).sum();
        let ratio = if comp != 0 { raw as f64 / comp as f64 } else { 0.0 };
        // codecs
        let mut codec_counts: Vec<(i32, usize)> = Vec::new();
        for rg in &m.row_groups {
            for c in &rg.columns {
                if let Some(e) = codec_counts.iter_mut().find(|e| e.0 == c.codec) { e.1 += 1; } else { codec_counts.push((c.codec, 1)); }
            }
        }
        let codecs = codec_counts.iter().map(|(c, n)| format!("{}({})", codec_debug(*c), n)).collect::<Vec<_>>().join(", ");
        let mut encs = std::collections::BTreeSet::new();
        for rg in &m.row_groups { for c in &rg.columns { for e in &c.encodings { encs.insert(encoding_name(*e)); } } }
        let enc_str = encs.into_iter().collect::<Vec<_>>().join(", ");
        let avg = if rows > 0 { raw / rows } else { 0 };
        vec![
            ("Format version".into(), m.version.to_string()),
            ("Created by".into(), m.created_by.clone().unwrap_or_else(|| "—".into())),
            ("Rows".into(), format_number(rows)),
            ("Columns".into(), leaf_count(&m.root).to_string()),
            ("Row groups".into(), m.row_groups.len().to_string()),
            ("Size (raw)".into(), fmt_bytes_kib(raw)),
            ("Size (compressed)".into(), fmt_bytes_kib(comp)),
            ("Compression ratio".into(), format!("{:.2}x", ratio)),
            ("Codecs (cols)".into(), codecs),
            ("Encodings".into(), enc_str),
            ("Avg row size".into(), format!("{} B", avg)),
        ]
    }

    fn render_metadata(&self, frame: &mut Frame, area: Rect) {
        let pairs = self.metadata_lines();
        let lines: Vec<Line> = pairs.iter().map(|(l, v)| {
            Line::from(vec![
                Span::styled(format!("{:>18}", l), Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD)),
                Span::raw(" "),
                Span::raw(v.clone()),
            ])
        }).collect();
        let max_len = pairs.iter().map(|(_, v)| 19 + v.chars().count()).max().unwrap_or(0);
        let desired_w = (max_len + 4) as u16;
        let desired_h = (pairs.len() + 2) as u16;
        let v = Layout::vertical([Constraint::Fill(1), Constraint::Length(desired_h), Constraint::Fill(1)]).split(area);
        let h = Layout::horizontal([Constraint::Fill(1), Constraint::Length(desired_w), Constraint::Fill(1)]).split(v[1]);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title_top(Line::from(Span::styled("File Metadata", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))).centered());
        frame.render_widget(Paragraph::new(lines).block(block), h[1]);
    }

    fn schema_tree_width(&self, rg: bool, scrollable: bool) -> u16 {
        let max_byte = self.flat.iter().map(|n| n.tree_line.len()).max().unwrap_or(0) as u16;
        if rg && !scrollable {
            max_byte.max(24)
        } else {
            (max_byte + 1).max(25)
        }
    }

    fn render_schema_tree(&mut self, frame: &mut Frame, area: Rect, rg: bool) -> Rect {
        // Returns the remaining area to the right.
        let inner_h = (area.height as usize).saturating_sub(2);
        let scrollable = self.flat.len() > inner_h;
        let desired = self.schema_tree_width(rg, scrollable);
        let scroll_w: u16 = if scrollable { 1 } else { 0 };
        let left_w = desired.min(area.width.saturating_sub(scroll_w));
        let left = Rect::new(area.x, area.y, left_w, area.height);
        let scroll_rect = Rect::new(area.x + left_w, area.y, scroll_w, area.height);
        let right_x = area.x + left_w + scroll_w;
        let right = Rect::new(right_x, area.y, area.width.saturating_sub(left_w + scroll_w), area.height);
        // Build block with titles
        let mut bottom_spans = vec![
            Span::styled("Leaf", Style::default().fg(Color::White)),
            Span::raw(", "),
            Span::styled("Group", Style::default().fg(Color::Green)),
        ];
        if self.selected_schema.is_some() {
            bottom_spans.push(Span::raw(", "));
            bottom_spans.push(Span::styled("Selected", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
        }
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title_top(Line::from(Span::styled("Schema Tree", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))).centered())
            .title_bottom(Line::from(bottom_spans).centered());
        let items: Vec<ListItem> = self.flat.iter().enumerate().map(|(i, n)| {
            let style = if Some(i) == self.selected_schema {
                Style::default().fg(Color::Black).bg(Color::Yellow)
            } else if i == 0 {
                Style::default().fg(Color::LightYellow)
            } else if n.is_leaf {
                Style::default().fg(Color::White)
            } else {
                Style::default().fg(Color::Green)
            };
            ListItem::new(Line::from(Span::styled(n.tree_line.clone(), style)))
        }).collect();
        let list = List::new(items)
            .block(block)
            .highlight_style(Style::default().fg(Color::Black).bg(Color::Yellow))
            .highlight_symbol("");
        // clone state to render (we need &mut state while self borrowed for items - items owned, fine)
        frame.render_stateful_widget(list, left, &mut self.list_state);
        if scrollable && scroll_w > 0 {
            let offset = self.list_state.offset();
            let mut sstate = ScrollbarState::new(self.flat.len())
                .position(offset)
                .viewport_content_length(inner_h);
            let scrollbar = Scrollbar::new(ScrollbarOrientation::VerticalRight)
                .begin_symbol(None)
                .end_symbol(None)
                .track_symbol(Some("│"))
                .thumb_symbol("█");
            frame.render_stateful_widget(scrollbar, scroll_rect, &mut sstate);
        }
        right
    }

    fn leaf_stats(&self, leaf_idx: usize) -> (i64, i64, f64, String, i32, String, String, i64) {
        let mut comp: i64 = 0; let mut uncomp: i64 = 0;
        let mut encset: HashSet<String> = HashSet::new();
        let mut codec = 0i32;
        let mut nulls: i64 = 0;
        let mut min_s = "NULL".to_string(); let mut max_s = "NULL".to_string();
        let mut first_stats = true;
        // physical type from leaf node
        let phys = self.flat.iter().filter(|n| n.is_leaf).nth(leaf_idx).map(|n| n.physical.unwrap_or(6)).unwrap_or(6);
        for (ri, rg) in self.meta.row_groups.iter().enumerate() {
            if let Some(c) = rg.columns.get(leaf_idx) {
                comp += c.total_compressed_size;
                uncomp += c.total_uncompressed_size;
                if ri == 0 { codec = c.codec; }
                for e in &c.encodings { encset.insert(encoding_name(*e)); }
                if let Some(st) = &c.statistics {
                    nulls += st.null_count.unwrap_or(0);
                    if first_stats {
                        min_s = schema_stat(st.min_bytes(), phys);
                        max_s = schema_stat(st.max_bytes(), phys);
                        first_stats = false;
                    }
                }
            }
        }
        let ratio = if comp != 0 { uncomp as f64 / comp as f64 } else { 0.0 };
        let enc_str = encset.into_iter().collect::<Vec<_>>().join(", ");
        (comp, uncomp, ratio, enc_str, codec, min_s, max_s, nulls)
    }

    fn render_schema(&mut self, frame: &mut Frame, area: Rect) {
        // Need right area: render tree first (it computes layout), but tree needs &mut.
        // We render tree and get right rect, then table.
        let right = self.render_schema_tree(frame, area, false);
        let headers = ["Repetition", "Physical", "Compressed", "Uncompressed", "Ratio", "Encodings", "Compression", "Min", "Max", "Nulls"];
        // build all rows strings
        let mut all_rows: Vec<Vec<String>> = Vec::new();
        let mut is_group_row: Vec<bool> = Vec::new();
        for n in self.flat.iter().skip(1) {
            let rep = match n.repetition { Some(0) => "REQUIRED", Some(1) => "OPTIONAL", Some(2) => "REPEATED", _ => "REQUIRED" }.to_string();
            if n.is_leaf {
                let li = n.leaf_index.unwrap_or(0);
                let (comp, uncomp, ratio, enc, codec, mn, mx, nulls) = self.leaf_stats(li);
                all_rows.push(vec![rep, physical_name(n.physical.unwrap_or(6)).into(), fmt_bytes_kb(comp), fmt_bytes_kb(uncomp), format!("{:.2}x", ratio), enc, codec_debug(codec), mn, mx, nulls.to_string()]);
                is_group_row.push(false);
            } else {
                let mut r = vec![rep, "group".into()];
                r.resize(10, String::new());
                all_rows.push(r);
                is_group_row.push(true);
            }
        }
        // widths per column (max len + 1)
        let mut widths: Vec<u16> = headers.iter().map(|h| h.len() as u16).collect();
        for r in &all_rows {
            for (i, c) in r.iter().enumerate() { widths[i] = widths[i].max(c.len() as u16); }
        }
        let visible_cols = (((right.width as usize).saturating_sub(4)) / 12).max(1);
        let max_start = headers.len().saturating_sub(visible_cols);
        let start = self.schema_col_offset.min(max_start);
        let header_row = Row::new(headers[start..].iter().map(|h| Cell::from(*h).style(Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))).collect::<Vec<_>>());
        let rows: Vec<Row> = all_rows.iter().enumerate().map(|(ri, r)| {
            let cells: Vec<Cell> = r[start..].iter().enumerate().map(|(ci, c)| {
                let actual_col = start + ci;
                if is_group_row[ri] && actual_col < 2 {
                    Cell::from(c.clone()).style(Style::default().fg(Color::Green))
                } else { Cell::from(c.clone()) }
            }).collect();
            Row::new(cells)
        }).collect();
        let constraints: Vec<Constraint> = widths[start..].iter().map(|w| Constraint::Length(w + 1)).collect();
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title_top(Line::from(Span::styled("Column Statistics", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD))).centered());
        let table = RTable::new(rows, constraints)
            .header(header_row)
            .block(block)
            .row_highlight_style(Style::default().fg(Color::Black).bg(Color::Yellow))
            .highlight_symbol("");
        frame.render_stateful_widget(table, right, &mut self.table_state);
    }

    fn render_rowgroups(&mut self, frame: &mut Frame, area: Rect) {
        let right = self.render_schema_tree(frame, area, true);
        if self.meta.row_groups.is_empty() { return; }
        let n_rg = self.meta.row_groups.len();
        let sel = self.selected_rg.min(n_rg - 1);
        if self.selected_schema.is_some() {
            self.render_rg_detail(frame, right, sel);
        } else {
            self.render_rg_overview(frame, right, sel);
        }
    }

    fn gauge_block(&self, frame: &mut Frame, area: Rect, sel: usize) {
        let n = self.meta.row_groups.len();
        let title = format!(" Row Group: {} / {} ", sel + 1, n);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_style(Style::default().fg(Color::Gray))
            .title_top(Line::from(Span::styled(title, Style::default().add_modifier(Modifier::BOLD))).left_aligned());
        let ratio = if n > 0 { (sel + 1) as f64 / n as f64 } else { 0.0 };
        let gauge = Gauge::default()
            .block(block)
            .gauge_style(Style::default().fg(Color::Blue))
            .label("")
            .ratio(ratio);
        frame.render_widget(gauge, area);
    }

    fn render_rg_overview(&mut self, frame: &mut Frame, area: Rect, sel: usize) {
        let v = Layout::vertical([Constraint::Length(3), Constraint::Length(3), Constraint::Min(0)]).split(area);
        self.gauge_block(frame, v[0], sel);
        // cards
        let rg = &self.meta.row_groups[sel];
        let total_rows: i64 = self.meta.row_groups.iter().map(|r| r.num_rows).sum();
        let total_comp: i64 = self.meta.row_groups.iter().map(|r| r.compressed()).sum();
        let total_uncomp: i64 = self.meta.row_groups.iter().map(|r| r.uncompressed()).sum();
        let sel_ratio = if rg.compressed() != 0 { rg.uncompressed() as f64 / rg.compressed() as f64 } else { 0.0 };
        let tot_ratio = if total_comp != 0 { total_uncomp as f64 / total_comp as f64 } else { 0.0 };
        let cards: Vec<(&str, String, String)> = vec![
            ("Rows", format_number(rg.num_rows), format_number(total_rows)),
            ("Compressed", fmt_bytes_kib(rg.compressed()), fmt_bytes_kib(total_comp)),
            ("Uncompressed", fmt_bytes_kib(rg.uncompressed()), fmt_bytes_kib(total_uncomp)),
            ("Ratio", format!("{:.2}", sel_ratio), format!("{:.2}", tot_ratio)),
        ];
        let card_area = Layout::horizontal([Constraint::Percentage(25), Constraint::Percentage(25), Constraint::Percentage(25), Constraint::Percentage(25)]).split(v[1]);
        for (i, (title, value, total)) in cards.iter().enumerate() {
            let bottom = Line::from(vec![
                Span::styled(value.clone(), Style::default().fg(Color::LightCyan)),
                Span::styled(" / ", Style::default().fg(Color::White)),
                Span::styled(total.clone(), Style::default().fg(Color::LightMagenta)),
            ]).style(Style::default().add_modifier(Modifier::BOLD)).centered();
            let block = Block::default()
                .borders(Borders::ALL)
                .border_style(Style::default().fg(Color::Blue))
                .title_top(Line::from(Span::styled(*title, Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD))).left_aligned())
                .title_bottom(bottom);
            let p = Paragraph::new(Line::from(Span::styled(value.clone(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))))
                .block(block)
                .alignment(Alignment::Center);
            frame.render_widget(p, card_area[i]);
        }
        // charts in left half
        let charts_area = v[2];
        let chart_w = (charts_area.width + 1) / 2;
        let chart_col = Rect::new(charts_area.x, charts_area.y, chart_w, charts_area.height);
        let cv = Layout::vertical([Constraint::Percentage(50), Constraint::Percentage(50)]).split(chart_col);
        self.render_chart1(frame, cv[0]);
        self.render_chart2(frame, cv[1]);
    }

    fn x_labels(&self) -> Vec<Span<'static>> {
        (0..self.meta.row_groups.len()).map(|i| Span::raw(format!("{}", i + 1))).collect()
    }
    fn x_bounds(&self) -> [f64; 2] {
        let n = self.meta.row_groups.len();
        [0.0, (n.saturating_sub(1)) as f64]
    }

    fn render_chart1(&self, frame: &mut Frame, area: Rect) {
        let max_size = self.chart1_comp.iter().chain(self.chart1_uncomp.iter()).map(|p| p.1).fold(0.0f64, f64::max);
        let y_max = max_size * 1.5;
        let labels: Vec<Span> = (0..4).map(|i| {
            let val = if y_max > 0.0 { y_max * i as f64 / 4.0 } else { i as f64 };
            Span::raw(fmt_axis(val))
        }).collect();
        let datasets = vec![
            Dataset::default()
                .name("Compressed")
                .marker(symbols::Marker::Dot)
                .graph_type(GraphType::Scatter)
                .style(Style::default().fg(Color::Blue))
                .data(&self.chart1_comp),
            Dataset::default()
                .name("Uncompressed")
                .marker(symbols::Marker::Dot)
                .graph_type(GraphType::Scatter)
                .style(Style::default().fg(Color::Red))
                .data(&self.chart1_uncomp),
        ];
        let title_line = Line::from(vec![
            Span::styled("Compressed", Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD)),
            Span::raw(" vs "),
            Span::styled("Uncompressed", Style::default().fg(Color::LightRed).add_modifier(Modifier::BOLD)),
            Span::raw(" (B)"),
        ]).centered();
        let block = Block::default()
            .title_top(title_line)
            .title_bottom(Line::from(Span::styled("Row Group", Style::default().fg(Color::DarkGray))).left_aligned());
        let chart = Chart::new(datasets)
            .block(block)
            .x_axis(Axis::default()
                .style(Style::default().fg(Color::White))
                .bounds(self.x_bounds())
                .labels(self.x_labels()))
            .y_axis(Axis::default()
                .style(Style::default().fg(Color::White))
                .bounds([0.0, if y_max > 0.0 { y_max } else { 1.0 }])
                .labels(labels)
                .labels_alignment(Alignment::Left))
            .legend_position(Some(LegendPosition::TopRight));
        frame.render_widget(chart, area);
    }

    fn render_chart2(&self, frame: &mut Frame, area: Rect) {
        let max_ratio = self.chart2_ratio.iter().map(|p| p.1).fold(0.0f64, f64::max);
        let y_min = 1.0f64;
        let y_max = max_ratio * 1.1;
        let labels: Vec<Span> = (0..4).map(|i| {
            let val = y_min + (y_max - y_min) * i as f64 / 4.0;
            Span::raw(format!("{:.1}x", val))
        }).collect();
        let datasets = vec![
            Dataset::default()
                .marker(symbols::Marker::Dot)
                .graph_type(GraphType::Scatter)
                .style(Style::default().fg(Color::Yellow))
                .data(&self.chart2_ratio),
        ];
        let block = Block::default()
            .title_top(Line::from(Span::styled("Compression Ratio", Style::default().fg(Color::Yellow))).left_aligned())
            .title_bottom(Line::from(Span::styled("Row Group", Style::default().fg(Color::DarkGray))).left_aligned());
        let chart = Chart::new(datasets)
            .block(block)
            .x_axis(Axis::default()
                .style(Style::default().fg(Color::White))
                .bounds(self.x_bounds())
                .labels(self.x_labels()))
            .y_axis(Axis::default()
                .style(Style::default().fg(Color::White))
                .bounds([y_min, y_max])
                .labels(labels)
                .labels_alignment(Alignment::Left));
        frame.render_widget(chart, area);
    }

    fn render_rg_detail(&mut self, frame: &mut Frame, area: Rect, sel: usize) {
        let v = Layout::vertical([Constraint::Length(3), Constraint::Length(1), Constraint::Length(3), Constraint::Min(0)]).split(area);
        self.gauge_block(frame, v[0], sel);
        let flat_idx = self.selected_schema.unwrap_or(0);
        let leaf_idx = self.flat[flat_idx].leaf_index.unwrap_or(0);
        let rg = &self.meta.row_groups[sel];
        let Some(chunk) = rg.columns.get(leaf_idx).cloned() else { return };
        let col_path = chunk.path.join(".");
        // separator
        let quoted = format!("\"{}\"", col_path);
        let title_len = 9 + quoted.chars().count() + 1;
        let w = v[1].width as usize;
        let left_dashes = w.saturating_sub(title_len) / 2;
        let right_dashes = w.saturating_sub(title_len + left_dashes);
        let sep = Line::from(vec![
            Span::styled("─".repeat(left_dashes), Style::default().fg(Color::Blue)),
            Span::styled(" Column: ", Style::default().fg(Color::Blue)),
            Span::styled(quoted, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
            Span::styled(format!(" {}", "─".repeat(right_dashes)), Style::default().fg(Color::Blue)),
        ]);
        frame.render_widget(Paragraph::new(sep), v[1]);
        // indicator cards
        let indicators: Vec<(&str, bool)> = vec![
            ("Statistics", chunk.statistics.is_some()),
            ("Dict Page", chunk.dictionary_page_offset.is_some()),
            ("Bloom Filter", chunk.bloom_filter_offset.is_some()),
            ("Page Stats", chunk.has_encoding_stats),
        ];
        let card_area = Layout::horizontal([Constraint::Percentage(25), Constraint::Percentage(25), Constraint::Percentage(25), Constraint::Percentage(25)]).split(v[2]);
        for (i, (title, present)) in indicators.iter().enumerate() {
            let color = if *present { Color::Green } else { Color::Red };
            let symbol = if *present { "✓" } else { "✗" };
            let block = Block::default()
                .borders(Borders::ALL)
                .border_style(Style::default().fg(color))
                .title_top(Line::from(Span::styled(*title, Style::default().add_modifier(Modifier::BOLD))).left_aligned());
            let p = Paragraph::new(Line::from(Span::styled(symbol, Style::default().fg(color).add_modifier(Modifier::BOLD))))
                .block(block)
                .alignment(Alignment::Center);
            frame.render_widget(p, card_area[i]);
        }
        // lower: metadata/stats left, pages right
        let lower = Layout::horizontal([Constraint::Percentage(38), Constraint::Percentage(62)]).split(v[3]);
        let ratio = if chunk.total_compressed_size != 0 { chunk.total_uncompressed_size as f64 / chunk.total_compressed_size as f64 } else { 0.0 };
        let meta_rows: Vec<(String, String)> = vec![
            ("File Offset (B)".into(), format_number(chunk.file_offset)),
            ("Compressed Size".into(), fmt_bytes_kib(chunk.total_compressed_size)),
            ("Uncompressed Size".into(), fmt_bytes_kib(chunk.total_uncompressed_size)),
            ("Compression Ratio".into(), format!("{:.2}x", ratio)),
            ("Compression Type".into(), codec_debug(chunk.codec)),
        ];
        let mut left_chunks = vec![Constraint::Length(7)];
        if chunk.statistics.is_some() { left_chunks.push(Constraint::Length(6)); }
        left_chunks.push(Constraint::Min(0));
        let lv = Layout::vertical(left_chunks).split(lower[0]);
        render_kv_table(frame, lv[0], "Metadata", Color::Blue, &meta_rows, true);
        if let Some(st) = &chunk.statistics {
            let phys = chunk.physical_type;
            let stat_rows: Vec<(String, String)> = vec![
                ("Min".into(), rg_stat(st.min_bytes(), phys)),
                ("Max".into(), rg_stat(st.max_bytes(), phys)),
                ("Null Count".into(), st.null_count.map(|n| n.to_string()).unwrap_or_else(|| "0".into())),
                ("Distinct Count".into(), st.distinct_count.map(|n| n.to_string()).unwrap_or_else(|| "N/A".into())),
            ];
            render_kv_table(frame, lv[1], "Statistics", Color::Magenta, &stat_rows, false);
        }
        // Pages
        let phys = chunk.physical_type;
        let leaf_node = &self.flat[flat_idx];
        let _ = leaf_node;
        let tl = node_at(&self.meta.root, &leaf_node.node_path).type_length.unwrap_or(0);
        let infos = read_column(&self.file, &chunk, phys, tl, 0, 0, true).map(|(_, i)| i).unwrap_or_default();
        let header = Row::new(["#", "Page Type", "Size", "Rows", "Encoding"].iter().map(|h| Cell::from(*h).style(Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))).collect::<Vec<_>>());
        let rows: Vec<Row> = infos.iter().enumerate().map(|(i, p)| {
            Row::new(vec![
                Cell::from((i + 1).to_string()).style(Style::default().fg(Color::White)),
                Cell::from(page_type_name(p.page_type)).style(Style::default().fg(Color::Cyan)),
                Cell::from(fmt_bytes_kib(p.uncompressed_size)).style(Style::default().fg(Color::White)),
                Cell::from(format_number(p.num_values)).style(Style::default().fg(Color::White)),
                Cell::from(encoding_label(p.encoding)).style(Style::default().fg(Color::Green)),
            ])
        }).collect();
        let block = Block::default()
            .borders(Borders::ALL)
            .border_style(Style::default().fg(Color::DarkGray))
            .title_top(Line::from("Pages").left_aligned());
        let table = RTable::new(rows, [Constraint::Length(3), Constraint::Min(20), Constraint::Min(21), Constraint::Min(14), Constraint::Min(20)])
            .header(header)
            .block(block);
        frame.render_widget(table, lower[1]);
    }
}

fn render_kv_table(frame: &mut Frame, area: Rect, title: &str, border: Color, rows_kv: &[(String, String)], cyan_labels: bool) {
    let rows: Vec<Row> = rows_kv.iter().map(|(k, v)| {
        let label_style = if cyan_labels {
            Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)
        } else {
            Style::default().add_modifier(Modifier::BOLD)
        };
        Row::new(vec![
            Cell::from(k.clone()).style(label_style),
            Cell::from(v.clone()).style(Style::default().fg(Color::White)),
        ])
    }).collect();
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(border))
        .title_top(Line::from(title.to_string()).left_aligned());
    let table = RTable::new(rows, [Constraint::Length(18), Constraint::Min(0)]).block(block);
    frame.render_widget(table, area);
}

fn page_type_name(t: i32) -> String {
    match t { 0 => "Data Page".into(), 1 => "Index Page".into(), 2 => "Dictionary Page".into(), 3 => "Data Page V2".into(), _ => "Unknown".into() }
}
fn encoding_label(e: i32) -> String {
    match e {
        0 => "Plain".into(), 2 => "Plain Dictionary".into(), 3 => "RLE".into(), 8 => "RLE Dictionary".into(),
        4 => "Bit Packed".into(), 5 => "Delta Binary Packed".into(), 6 => "Delta Length Byte Array".into(),
        7 => "Delta Byte Array".into(), 9 => "Byte Stream Split".into(), 1 => "Group Var Int".into(),
        _ => "Unknown".into(),
    }
}
