mod fmt;
mod meta;
mod page;
mod thrift;
mod ui;

use clap::{Arg, Command};
use ratatui::crossterm::event::{self, Event};
use std::fs::File;
use std::io::{self, Read};
use ui::App;

fn cli() -> Command {
    Command::new("parqeye")
        .about("Command line tool to visualize parquet files")
        .version("0.0.2")
        .arg(
            Arg::new("PATH")
                .help("Path to the parquet file")
                .required(true),
        )
}

fn other(msg: String) -> io::Error {
    io::Error::new(io::ErrorKind::Other, msg)
}

fn run(terminal: &mut ratatui::DefaultTerminal, path: &str) -> io::Result<()> {
    // Load file (after terminal init, like the original).
    let mut f = File::open(path).map_err(|e| other(e.to_string()))?;
    let mut bytes = Vec::new();
    f.read_to_end(&mut bytes).map_err(|e| other(format!("External: {}", e)))?;
    let meta = meta::parse_footer(&bytes).map_err(other)?;
    let table = data::load_table(&bytes, &meta).map_err(other)?;
    let mut app = App::new(path.to_string(), meta, bytes, table);
    loop {
        terminal.draw(|frame| app.render(frame))?;
        if let Event::Key(key) = event::read()? {
            app.on_key(key);
            if app.should_quit { break; }
        }
    }
    Ok(())
}

fn main() -> io::Result<()> {
    let matches = cli().get_matches();
    let path = matches.get_one::<String>("PATH").expect("PATH required").clone();
    let mut terminal = ratatui::init();
    let result = run(&mut terminal, &path);
    ratatui::restore();
    result
}
