            app.on_key(key);
            if app.should_quit { break; }
        }
    }
    Ok(())
}

fn main() -> io::Result<()> {
    let matches = cli().get_matches();
    let path = matches.get_one::<String>("PATH").expect("PATH required").clone();
    let mut terminal = ratatui::init();
    let result = run(&mut terminal, &path);
    ratatui::restore();
    result
}
