fn trim_fixed(s: &str) -> String {
    if !s.contains('.') { return s.to_string(); }
    let t = s.trim_end_matches('0');
    if t.ends_with('.') { format!("{}0", t) } else { t.to_string() }
}

macro_rules! float_formatter {
    ($name:ident, $t:ty) => {
        pub fn $name(v: $t) -> String {
