    if tc==3: return bytes([v & 0xff])
    if tc in (4,5,6): return zigzag(v)
    if tc==7: return struct.pack('<d', v)
    if tc==8:
        if isinstance(v,str): v=v.encode()
        return varint(len(v))+v
    if tc in (9,10):
        et, items = v
        if len(items)<15: hdr=bytes([(len(items)<<4)|et])
        else: hdr=bytes([0xf0|et])+varint(len(items))
        return hdr+b''.join(write_value(et,x) for x in items)
    if tc==12:
        return write_struct(v)
    raise ValueError(tc)

def write_struct(fields):
    out=bytearray(); last=0
    for fid,tc,v in fields:
        delta=fid-last
        if tc in (1,2):
            # bool field: tc is 1 if v else 2 expected by caller, but allow tc=1/2 directly
            t = tc
            if 0<delta<=15: out.append((delta<<4)|t)
            else: out.append(t); out += zigzag(fid)
            last=fid; continue
        if 0<delta<=15: out.append((delta<<4)|tc)
        else: out.append(tc); out += zigzag(fid)
        last=fid
        out += write_value(tc,v)
    out.append(0)
    return bytes(out)

def boolfield(fid, v):
    return (fid, 1 if v else 2, None)

def plain_values(phys, vals, type_length=0):
    out=bytearray()
    if phys==0:
        # pack LSB
        cur=0
        for i,v in enumerate(vals):
            if v: cur |= 1<<(i%8)
            if i%8==7 or i==len(vals)-1: out.append(cur); cur=0
    elif phys==1:
        for v in vals: out+=struct.pack('<i',v)
    elif phys==2:
        for v in vals: out+=struct.pack('<q',v)
    elif phys==3:
        for v in vals: out+=v  # 12 bytes each
    elif phys==4:
        for v in vals: out+=struct.pack('<f',v)
    elif phys==5:
        for v in vals: out+=struct.pack('<d',v)
    elif phys==6:
        for v in vals:
            if isinstance(v,str): v=v.encode()
            out+=struct.pack('<i',len(v))+v
    elif phys==7:
        for v in vals:
            assert len(v)==type_length, (v,type_length)
            out+=v
    return bytes(out)

def rle_levels(levels, max_level):
    if max_level==0: return b''
    bw=max_level.bit_length()
    # one bitpacked run for all (groups of 8)
    groups=(len(levels)+7)//8
    data=bytearray(varint((groups<<1)|1))
    # pack LSB
    bits=[]
    for v in levels:
        for i in range(bw): bits.append((v>>i)&1)
    while len(bits)%8: bits.append(0)
    for i in range(0,len(bits),8):
        b=0
        for j,bit in enumerate(bits[i:i+8]): b|=bit<<j
        data.append(b)
    return struct.pack('<i',len(data))+bytes(data)

def make_page(phys, type_length, cells, max_def, max_rep, codec=0, compress_fn=None):
    # cells: list of (rep,def,value or None)
    reps=[c[0] for c in cells]; defs=[c[1] for c in cells]
    vals=[c[2] for c in cells if c[1]==max_def]
    body = rle_levels(reps,max_rep) + rle_levels(defs,max_def) + plain_values(phys,vals,type_length)
    comp_body = compress_fn(body) if compress_fn else body
    dph=[(1,5,len(cells)),(2,5,0),(3,5,3),(4,5,3)]
    hdr=[(1,5,0),(2,5,len(body)),(3,5,len(comp_body)),(5,12,dph)]
    h=write_struct(hdr)
    return h+comp_body, len(body), len(h)+len(comp_body)

def schema_elem(name, phys=None, rep=None, nchild=None, converted=None, scale=None, precision=None, type_length=None, logical=None):
    f=[]
    if phys is not None: f.append((1,5,phys))
    if type_length is not None: f.append((2,5,type_length))
    if rep is not None: f.append((3,5,rep))
    f.append((4,8,name))
    if nchild is not None: f.append((5,5,nchild))
    if converted is not None: f.append((6,5,converted))
    if scale is not None: f.append((7,5,scale))
    if precision is not None: f.append((8,5,precision))
    if logical is not None: f.append((10,12,logical))
    return f

def stats_struct(minb=None,maxb=None,nulls=None,distinct=None,old=False):
    f=[]
    if old:
        if maxb is not None: f.append((1,8,maxb))
        if minb is not None: f.append((2,8,minb))
    if nulls is not None: f.append((3,6,nulls))
    if distinct is not None: f.append((4,6,distinct))
    if not old:
        if maxb is not None: f.append((5,8,maxb))
        if minb is not None: f.append((6,8,minb))
    return f

def stat_bytes(phys,v):
    if v is None: return None
    if isinstance(v,bytes): return v
    if phys==0: return b'\x01' if v else b'\x00'
    if phys==1: return struct.pack('<i',v)
    if phys==2: return struct.pack('<q',v)
    if phys==4: return struct.pack('<f',v)
    if phys==5: return struct.pack('<d',v)
    if phys==6: return v.encode() if isinstance(v,str) else v
    return v

# columns spec for writer:
#   dict(name, phys, type_length, rep (0 req,1 opt), converted, logical, scale, precision)
# row_groups: list of dict(rows=[ [v,...], ...], stats=[(min,max,nulls) per col or None], codec, compress_fn)
def write_parquet(path, columns, row_groups, created_by=None, version=1, kv=None):
    elems=[schema_elem('schema', nchild=len(columns))]
    for c in columns:
        elems.append(schema_elem(c['name'], phys=c['phys'], rep=c.get('rep',1), converted=c.get('converted'), scale=c.get('scale'), precision=c.get('precision'), type_length=c.get('type_length'), logical=c.get('logical')))
    data=bytearray(b'PAR1')
    rg_structs=[]
    total_rows=0
    for rg in row_groups:
        rows=rg['rows']; total_rows+=len(rows)
        codec=rg.get('codec',0); comp=rg.get('compress_fn')
        col_structs=[]; rg_unc=0; rg_comp=0
        for ci,c in enumerate(columns):
            max_def=1 if c.get('rep',1)==1 else 0
            cells=[]
            for row in rows:
                v=row[ci]
                if v is None: cells.append((0,0,None))
                else: cells.append((0,max_def,v))
            start=len(data)
            page,unc,total = make_page(c['phys'], c.get('type_length',0), cells, max_def, 0, codec, comp)
            data+=page
            end=len(data)
            # total_uncompressed/compressed in metadata include header bytes: parquet defines as total size of page data + header? Observed = chunk byte length.
            md=[(1,5,c['phys']),(2,9,(5,[0,3])),(3,9,(8,[c['name']])),(4,5,codec),(5,6,len(rows)),(6,6,total),(7,6,total),(9,6,start)]
            st = (rg.get('stats') or [None]*len(columns))[ci]
            if st is not None:
                mn,mx,nc = st
                md.append((12,12,stats_struct(stat_bytes(c['phys'],mn),stat_bytes(c['phys'],mx),nc)))
            md.sort(key=lambda x:x[0])
            col_structs.append([(2,6,end),(3,12,md)])
            rg_unc+=total; rg_comp+=total
        rg_structs.append([(1,9,(12,col_structs)),(2,6,rg_unc),(3,6,len(rows)),(6,6,rg_comp)])
    meta=[(1,5,version),(2,9,(12,elems)),(3,6,total_rows),(4,9,(12,rg_structs))]
    if kv:
        meta.append((5,9,(12,[[(1,8,k)]+ ([(2,8,v)] if v is not None else []) for k,v in kv])))
    if created_by is not None: meta.append((6,8,created_by))
    meta_bytes=write_struct(meta)
    data+=meta_bytes+struct.pack('<I',len(meta_bytes))+b'PAR1'
    open(path,'wb').write(bytes(data))
