pub fn fmt_duration_ns(ns: i64) -> String {
    if ns == 0 { return "0ns".into(); }
    let neg = ns < 0;
    let mut rem = (ns as i128).unsigned_abs();
    let units: [(u128, &str); 7] = [
        (86_400_000_000_000, "d"),
        (3_600_000_000_000, "h"),
        (60_000_000_000, "m"),
