        (1_000_000, "ms"),
        (1_000, "us"),
        (1, "ns"),
    ];
    let mut parts = Vec::new();
    for (size, name) in units {
        if rem >= size {
            parts.push(format!("{}{}", rem / size, name));
            rem %= size;
        }
    }
    let s = parts.join(" ");
    if neg { format!("-{}", s) } else { s }
}
'''
