# Schema node dict: {name, phys (None=group), rep (0/1/2), children, converted, logical, type_length, scale, precision}
def flatten_schema(node, out):
    out.append(node)
    for ch in node.get('children', []):
        flatten_schema(ch, out)

def shred(node, value, rep, def_level, cells, leaf_index_map, node_id, first_rep_of_record=True):
    # returns nothing; appends (rep,def,val) to cells[leaf_id]
    rep_type = node.get('rep', 0)
    # Handle null for optional node (group or primitive), when value is None
    if rep_type == 1 and value is None:
        emit_nulls(node, rep, def_level, cells, leaf_index_map)
        return
    if rep_type == 2:
        # value is a list
        if not value:
            emit_nulls(node, rep, def_level, cells, leaf_index_map)
            return
        # rep level of this repeated node = (number of repeated ancestors)+1 -- computed via node['_rep_level']
        for j, elem in enumerate(value):
            r = rep if j == 0 else node['_rep_level']
            if node.get('phys') is not None:
                cells[id(node)].append((r, def_level + 1, elem))
            else:
                # group: elem is dict
                for ch in node['children']:
                    shred(ch, elem.get(ch['name']) if isinstance(elem, dict) else None, r, def_level + 1, cells, leaf_index_map, node_id)
        return
    # not repeated
    d = def_level + (1 if rep_type == 1 else 0)
    if node.get('phys') is not None:
        cells[id(node)].append((rep, d, value))
    else:
        for ch in node['children']:
            shred(ch, value.get(ch['name']) if isinstance(value, dict) else None, rep, d, cells, leaf_index_map, node_id)

def emit_nulls(node, rep, def_level, cells, leaf_index_map):
    if node.get('phys') is not None:
        cells[id(node)].append((rep, def_level, None))
    else:
        for ch in node['children']:
            emit_nulls(ch, rep, def_level, cells, leaf_index_map)

def annotate_levels(node, def_level, rep_level):
    node['_def_before'] = def_level
    rep_type = node.get('rep', 0)
    if rep_type == 2:
        node['_rep_level'] = rep_level + 1
        d, r = def_level + 1, rep_level + 1
    elif rep_type == 1:
        d, r = def_level + 1, rep_level
    else:
        d, r = def_level, rep_level
    node['_max_def_here'] = d
    for ch in node.get('children', []):
        annotate_levels(ch, d, r)

def make_page_cells(phys, type_length, cells_list, max_def, max_rep):
    reps = [c[0] for c in cells_list]; defs = [c[1] for c in cells_list]
    vals = [c[2] for c in cells_list if c[1] == max_def]
    body = rle_levels(reps, max_rep) + rle_levels(defs, max_def) + plain_values(phys, vals, type_length)
    dph = [(1,5,len(cells_list)),(2,5,0),(3,5,3),(4,5,3)]
    hdr = [(1,5,0),(2,5,len(body)),(3,5,len(body)),(5,12,dph)]
    h = write_struct(hdr)
    return h + body, len(h) + len(body)

def write_nested(path, root, records, created_by='nested-writer'):
    flat = []
    flatten_schema(root, flat)
    annotate_levels(root, 0, 0)
    leaves = [n for n in flat if n.get('phys') is not None]
    elems = []
    for n in flat:
        elems.append(schema_elem(n['name'], phys=n.get('phys'), rep=n.get('rep'), nchild=(len(n['children']) if n.get('children') else None), converted=n.get('converted'), scale=n.get('scale'), precision=n.get('precision'), type_length=n.get('type_length'), logical=n.get('logical')))
    # shred
    cells = {id(leaf): [] for leaf in leaves}
    leaf_index_map = {}
    for rec in records:
        # root is required group; first cell of each leaf in a record must have rep=0.
        # shred handles this: we call with rep=0 for root children.
        for ch in root['children']:
            shred(ch, rec.get(ch['name']), 0, 0, cells, leaf_index_map, id(ch))
    # leaf path names
    def leaf_paths(node, prefix, out):
        if node.get('phys') is not None:
            out.append(prefix + [node['name']])
        else:
            for ch in node.get('children', []):
                leaf_paths(ch, prefix + [node['name']] if node is not root else prefix, out)
    paths = []
    for ch in root['children']:
        leaf_paths(ch, [], paths)
    data = bytearray(b'PAR1')
    col_structs = []
    total_sz = 0
    for leaf, pth in zip(leaves, paths):
        max_def = leaf['_max_def_here']
        max_rep = 0
        # compute max_rep from rep levels along path: store during annotate? Use leaf rep from cells max
        max_rep = max([c[0] for c in cells[id(leaf)]] + [0])
        # Actually max_rep should be total repeated ancestors; cells may not attain it if lists are singletons. Walk path:
        # We stored _rep_level on repeated nodes; find max in flat ancestors is hard here; recompute by traversing root to leaf.
        max_rep = compute_max_rep(root, leaf)
        start = len(data)
        page, total = make_page_cells(leaf['phys'], leaf.get('type_length', 0), cells[id(leaf)], max_def, max_rep)
        data += page
        end = len(data)
        md = [(1,5,leaf['phys']),(2,9,(5,[0,3])),(3,9,(8,pth)),(4,5,0),(5,6,len(cells[id(leaf)])),(6,6,total),(7,6,total),(9,6,start)]
        col_structs.append([(2,6,end),(3,12,md)])
        total_sz += total
    rg = [(1,9,(12,col_structs)),(2,6,total_sz),(3,6,len(records)),(6,6,total_sz)]
    meta = [(1,5,1),(2,9,(12,elems)),(3,6,len(records)),(4,9,(12,[rg])),(6,8,created_by)]
    mb = write_struct(meta)
    data += mb + struct.pack('<I', len(mb)) + b'PAR1'
    open(path, 'wb').write(bytes(data))

def compute_max_rep(node, target, rep_level=0):
    rep_type = node.get('rep', 0)
    r = rep_level + (1 if rep_type == 2 else 0)
    if node is target:
        return r
    for ch in node.get('children', []):
        v = compute_max_rep(ch, target, r)
        if v is not None:
            return v
    return None
