mod ffi {
    use std::os::raw::{c_char, c_int, c_void};
    use std::sync::OnceLock;

    pub type ZstdDecompress = unsafe extern "C" fn(*mut c_void, usize, *const c_void, usize) -> usize;
    pub type ZstdIsError = unsafe extern "C" fn(usize) -> u32;
    pub type BrotliDecompress = unsafe extern "C" fn(usize, *const u8, *mut usize, *mut u8) -> c_int;

    unsafe fn load_sym(lib: &str, sym: &str) -> Option<usize> {
        let lib_c = std::ffi::CString::new(lib).ok()?;
        let handle = libc::dlopen(lib_c.as_ptr(), libc::RTLD_NOW | libc::RTLD_GLOBAL);
        if handle.is_null() { return None; }
        let sym_c = std::ffi::CString::new(sym).ok()?;
        let p = libc::dlsym(handle, sym_c.as_ptr());
        if p.is_null() { None } else { Some(p as usize) }
    }

    pub fn zstd_fns() -> Option<(ZstdDecompress, ZstdIsError)> {
        static CACHE: OnceLock<Option<(usize, usize)>> = OnceLock::new();
        let v = CACHE.get_or_init(|| unsafe {
            Some((load_sym("libzstd.so.1", "ZSTD_decompress")?, load_sym("libzstd.so.1", "ZSTD_isError")?))
        });
        v.map(|(a, b)| unsafe { (std::mem::transmute(a), std::mem::transmute(b)) })
    }

    pub fn brotli_fn() -> Option<BrotliDecompress> {
        static CACHE: OnceLock<Option<usize>> = OnceLock::new();
        let v = CACHE.get_or_init(|| unsafe { load_sym("libbrotlidec.so.1", "BrotliDecoderDecompress") });
        v.map(|a| unsafe { std::mem::transmute(a) })
    }
    #[allow(dead_code)]
    pub type _Unused = c_char;
}

'''
